export default "<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\">\n<title>__PAGE_TITLE__</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Noto+Serif+KR:wght@500;700;900&family=Pretendard:wght@400;500;600;700&family=IBM+Plex+Mono:wght@500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --navy:#132845;\n    --navy-2:#1d3a63;\n    --steel:#4a6187;\n    --gold:#b8863b;\n    --gold-l:#e4c78a;\n    --paper:#f6f3ec;\n    --card:#ffffff;\n    --ink:#1b2330;\n    --ink-soft:#5a6472;\n    --line:#dcd6c8;\n    --teal:#1f6f66;\n    --teal-bg:#e7f2ef;\n    --indigo:#463b8a;\n    --indigo-bg:#eeecf7;\n    --risk-hi:#a23b2e;\n    --risk-hi-bg:#f7e6e2;\n    --risk-mid:#b8863b;\n    --risk-mid-bg:#f7edd9;\n    --good:#2e7d5b;\n    --good-bg:#e5f2ea;\n  }\n  *{box-sizing:border-box;}\n  html,body{margin:0;padding:0;}\n  body{\n    background:#dcd5c4;\n    font-family:'Pretendard','Noto Sans KR',sans-serif;\n    font-size:14px;\n    color:var(--ink);\n    -webkit-font-smoothing:antialiased;\n  }\n  .page-shell{\n    max-width:900px;\n    margin:28px auto;\n    background:var(--paper);\n    box-shadow:0 10px 40px rgba(19,40,69,0.25);\n  }\n  .mono{font-family:'IBM Plex Mono',monospace;}\n\n  /* ===== Side quick-nav map (wide screens only) ===== */\n  .side-navmap{\n    position:fixed; left:12px; top:80px; width:340px; max-height:82vh; overflow-y:auto;\n    background:var(--card); border:1px solid var(--line); border-radius:6px; padding:16px;\n    font-size:13px; box-shadow:0 4px 14px rgba(19,40,69,.15); z-index:40;\n  }\n  .side-navmap h5{margin:0 0 10px;font-size:12px;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.05em;font-family:'IBM Plex Mono',monospace;}\n  .side-navmap .snm-actions{display:flex;flex-direction:column;gap:7px;margin-bottom:16px;padding-bottom:14px;border-bottom:1px solid var(--line);}\n  .side-navmap .snm-action-btn{\n    font-family:'IBM Plex Mono',monospace;font-size:11.5px;background:var(--navy);color:#f4efe2;border:none;\n    padding:8px 10px;cursor:pointer;text-align:left;border-radius:3px;\n  }\n  .side-navmap .snm-action-btn:hover{background:var(--navy-2);}\n  .side-navmap .snm-domain{margin-bottom:14px;}\n  .side-navmap .snm-domain-title{font-weight:700;color:var(--navy);margin-bottom:6px;cursor:pointer;font-size:13px;line-height:1.4;}\n  .side-navmap .snm-domain-title:hover{color:var(--navy-2);text-decoration:underline;}\n  .side-navmap .snm-item-link{display:block;padding:5px 6px 5px 9px;color:var(--ink-soft);cursor:pointer;font-size:12.5px;border-left:2px solid transparent;line-height:1.45;border-radius:3px;}\n  .side-navmap .snm-item-top{display:flex;align-items:center;gap:6px;white-space:nowrap;}\n  .side-navmap .snm-item-code{display:inline-block;font-family:'IBM Plex Mono',monospace;font-size:10.5px;color:var(--steel);font-weight:700;flex:none;}\n  .side-navmap .snm-item-status{display:inline-block;flex:none;font-size:9px;font-weight:800;padding:1px 6px;border-radius:8px;font-family:'IBM Plex Mono',monospace;background:#eee;color:#8a8f99;}\n  .side-navmap .snm-item-status.st-complete{background:var(--good-bg);color:var(--good);}\n  .side-navmap .snm-item-status.st-inprogress{background:var(--risk-mid-bg);color:var(--risk-mid);}\n  .side-navmap .snm-item-status.st-notstarted{background:#ece7d9;color:#8a8f99;}\n  .side-navmap .snm-item-title-text{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:1px;}\n  .side-navmap .snm-item-link:hover{color:var(--navy-2);border-left-color:var(--gold);background:#f7f4ea;}\n  .side-navmap .snm-item-link.answered .snm-item-code{color:var(--good);}\n  .side-navmap .snm-item-link:hover .snm-item-title-text{white-space:normal;overflow:visible;text-overflow:clip;}\n  @media (max-width:1660px){ .side-navmap{display:none;} }\n  .side-navmap.force-show{display:block !important; z-index:200; box-shadow:0 10px 36px rgba(19,40,69,.4);}\n  .snm-close-btn{display:none;}\n  .side-navmap.force-show .snm-close-btn{\n    display:block; width:100%; margin-bottom:10px; font-family:'IBM Plex Mono',monospace; font-size:11.5px;\n    background:var(--risk-hi); color:#fff; border:none; padding:8px 10px; cursor:pointer; border-radius:3px;\n  }\n  #quickMenuBackdrop{display:none; position:fixed; inset:0; background:rgba(19,40,69,.35); z-index:190;}\n  #quickMenuBackdrop.show{display:block;}\n  #quickMenuFab{\n    display:none; position:fixed; left:16px; bottom:16px; z-index:150;\n    background:var(--navy); color:#f4efe2; border:none; border-radius:24px; padding:11px 18px;\n    font-family:'Pretendard'; font-weight:700; font-size:13px; cursor:pointer; box-shadow:0 4px 14px rgba(19,40,69,.35);\n  }\n  #quickMenuFab:hover{background:var(--navy-2);}\n  @media (max-width:1660px){ #quickMenuFab{display:block;} }\n  @media print{ .side-navmap, #quickMenuFab, #quickMenuBackdrop{display:none !important;} }\n\n  #allCompleteModal{\n    position:fixed; inset:0; z-index:300; background:rgba(19,40,69,.55);\n    display:flex; align-items:center; justify-content:center; padding:20px;\n  }\n  #allCompleteModal .acm-card{\n    background:var(--card); border-radius:10px; max-width:440px; width:100%;\n    padding:30px 28px 26px; text-align:center; box-shadow:0 16px 44px rgba(19,40,69,.4);\n  }\n  #allCompleteModal .acm-emoji{font-size:40px; margin-bottom:6px;}\n  #allCompleteModal h3{margin:0 0 10px; font-size:18px; color:var(--navy);}\n  #allCompleteModal p{margin:0 0 20px; font-size:13px; color:var(--ink); line-height:1.7;}\n  #allCompleteModal .acm-actions{display:flex; flex-direction:column; gap:8px; margin-bottom:16px;}\n  #allCompleteModal .acm-primary-btn{\n    background:var(--navy); color:#f4efe2; border:none; border-radius:6px; padding:12px;\n    font-family:'Pretendard'; font-weight:700; font-size:14px; cursor:pointer;\n  }\n  #allCompleteModal .acm-primary-btn:hover{background:var(--navy-2);}\n  #allCompleteModal .acm-secondary-btn{\n    background:transparent; color:var(--ink-soft); border:1px solid var(--line); border-radius:6px;\n    padding:10px; font-family:'Pretendard'; font-size:12.5px; cursor:pointer;\n  }\n  #allCompleteModal .acm-secondary-btn:hover{background:#f5f1e6;}\n  #allCompleteModal .acm-hint{\n    text-align:left; font-size:11.5px; color:var(--ink-soft); line-height:1.7;\n    background:#f5f1e6; border-left:3px solid var(--gold); padding:10px 12px; border-radius:0 4px 4px 0;\n  }\n  @media print{ #allCompleteModal{display:none !important;} }\n\n  /* ===== Header band ===== */\n  .hero{\n    background:linear-gradient(155deg,var(--navy) 0%,var(--navy-2) 62%,#24406b 100%);\n    color:#f4efe2;\n    padding:38px 44px 30px;\n    position:relative;\n    overflow:hidden;\n  }\n  .hero::after{\n    content:\"\";\n    position:absolute; right:-60px; top:-60px;\n    width:260px;height:260px;border-radius:50%;\n    border:1px solid rgba(228,199,138,0.18);\n  }\n  .hero::before{\n    content:\"\";\n    position:absolute; right:10px; top:40px;\n    width:170px;height:170px;border-radius:50%;\n    border:1px solid rgba(228,199,138,0.12);\n  }\n  .eyebrow{\n    font-family:'IBM Plex Mono',monospace;\n    letter-spacing:0.22em;\n    font-size:12px;\n    color:var(--gold-l);\n    text-transform:uppercase;\n    margin-bottom:14px;\n  }\n  .hero h1{\n    font-family:'Pretendard';font-weight:700;letter-spacing:-0.01em;\n    font-weight:900;\n    font-size:32px;\n    line-height:1.35;\n    margin:0 0 6px;\n  }\n  .hero .sub{\n    font-size:14px;\n    color:#c9d2e2;\n    max-width:520px;\n    line-height:1.7;\n  }\n  .hero-meta{\n    margin-top:22px;\n    display:flex;\n    gap:28px;\n    flex-wrap:wrap;\n    border-top:1px solid rgba(228,199,138,0.25);\n    padding-top:16px;\n  }\n  .hero-meta div{font-size:12px;color:#a9b4c8;}\n  .hero-meta strong{display:block;font-size:16px;color:#f4efe2;font-family:'IBM Plex Mono',monospace;margin-top:3px;}\n\n  /* ===== Instruction / info bar ===== */\n  .info-bar{\n    background:#efe8d4;\n    border-bottom:1px solid var(--line);\n    padding:20px 44px;\n  }\n  .info-bar h3{\n    font-family:'Pretendard';font-weight:700;letter-spacing:-0.01em;\n    font-size:14px;\n    margin:0 0 10px;\n    color:var(--navy);\n  }\n  .info-bar ol{margin:0;padding-left:18px;font-size:13.8px;line-height:1.9;color:#3a4150;}\n  .response-key-compact{\n    display:flex;align-items:center;flex-wrap:wrap;gap:14px;\n    background:var(--card);border:1px solid var(--line);border-radius:6px;\n    padding:9px 16px;margin-bottom:14px;font-size:13px;\n  }\n  .response-key-compact .rk-label{font-weight:700;color:var(--navy);flex:none;}\n  .response-key-compact .k-row{display:inline-flex;align-items:center;gap:5px;white-space:nowrap;}\n  .chip{\n    display:inline-flex;align-items:center;justify-content:center;\n    width:18px;height:18px;border:1.4px solid var(--navy-2);\n    font-size:10px;\n  }\n  .chip.na{border-style:dashed;color:var(--ink-soft);border-color:#9aa3b0;}\n  .wg-flow{display:flex;align-items:stretch;gap:6px;margin-bottom:14px;flex-wrap:wrap;}\n  .wg-step{\n    background:var(--card);border:1.5px solid var(--navy-2);border-radius:7px;padding:9px 12px;\n    flex:1 1 130px;min-width:120px;font-size:12px;color:var(--ink);position:relative;\n  }\n  .wg-step b{display:block;color:var(--navy);font-size:12.5px;margin-bottom:3px;}\n  .wg-arrow{display:flex;align-items:center;color:var(--gold);font-size:16px;flex:none;}\n  .info-guide-btn-row{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;flex-wrap:wrap;gap:8px;}\n  .info-guide-open-btn{\n    font-family:'Pretendard';font-weight:700;font-size:12.5px;background:var(--navy);color:#f4efe2;\n    border:none;padding:9px 16px;border-radius:6px;cursor:pointer;\n  }\n  .info-guide-open-btn:hover{background:var(--navy-2);}\n  .info-detail-toggle{margin-top:4px;}\n  .info-detail-toggle summary{cursor:pointer;font-size:12px;color:var(--navy-2);font-weight:600;padding:4px 0;}\n  .info-detail-toggle[open] summary{margin-bottom:6px;}\n\n  /* ===== Fill-in fields (dept / date) ===== */\n  .fill-grid{\n    display:grid;\n    grid-template-columns:repeat(4,1fr);\n    border-top:1px solid var(--line);\n  }\n  .fill-cell{\n    padding:12px 16px;\n    border-right:1px solid var(--line);\n    border-bottom:1px solid var(--line);\n  }\n  .fill-cell:last-child{border-right:none;}\n  .fill-cell label{\n    display:block;font-size:11.5px;letter-spacing:.06em;color:var(--ink-soft);\n    text-transform:uppercase;margin-bottom:6px;font-family:'IBM Plex Mono',monospace;\n  }\n  .fill-cell input[type=text], .fill-cell input[type=date]{\n    border:none;border-bottom:1px solid #9aa3b0;background:transparent;\n    width:100%;font-size:13px;font-family:inherit;padding:2px 0;color:var(--ink);\n  }\n  .fill-cell input:focus{outline:none;border-bottom-color:var(--navy-2);}\n  .interview-avail-row{\n    padding:10px 16px;border-top:none;border-bottom:1px solid var(--line);\n    background:#faf8f0;\n  }\n  .interview-avail-row label{\n    display:block;font-size:11.5px;color:var(--ink-soft);margin-bottom:6px;line-height:1.6;\n  }\n  .interview-avail-row input{\n    border:1px solid #c7c1b1;background:#fffdf8;width:100%;box-sizing:border-box;\n    font-size:12.5px;font-family:inherit;padding:7px 9px;\n  }\n\n  /* ===== Dashboard ===== */\n  .dash{\n    margin:26px 44px 0;\n    border:1px solid var(--navy);\n    background:var(--card);\n  }\n  .dash-head{\n    background:var(--navy);color:#f4efe2;\n    padding:12px 20px;\n    display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;row-gap:8px;\n  }\n  .dash-head h2{\n    font-family:'Pretendard';font-weight:700;letter-spacing:-0.01em;font-size:16px;margin:0;\n  }\n  /* [수정] 버튼이 늘어나면서(인쇄/CSV/JSON/인포그래픽/그룹웨어/이어작성/초기화 총 7개) 한 줄에 다\n     안 들어가는 화면 폭에서는 뒤쪽 버튼(특히 \"📥 저장한 JSON 불러와 이어작성\")이 가려지거나 화면\n     밖으로 밀려날 수 있었다. 줄바꿈을 허용해 버튼이 항상 다 보이도록 한다. */\n  .dash-head .dash-actions{display:flex;gap:8px;flex-wrap:wrap;}\n  .dash-btn{\n    font-family:'IBM Plex Mono',monospace;font-size:11.5px;\n    background:transparent;border:1px solid rgba(228,199,138,0.6);color:var(--gold-l);\n    padding:6px 11px;cursor:pointer;letter-spacing:.03em;\n  }\n  .dash-btn:hover{background:rgba(228,199,138,0.15);}\n  .dash-body{padding:20px;display:grid;grid-template-columns:1fr 1fr;gap:18px;}\n  .dash-card{border:1px solid var(--line);padding:14px 16px;}\n  .dash-card h4{\n    margin:0 0 10px;font-size:12px;color:var(--ink-soft);letter-spacing:.03em;\n    font-family:'IBM Plex Mono',monospace;text-transform:uppercase;\n  }\n  .progress-num{font-family:'Pretendard';font-weight:800;letter-spacing:-0.01em;font-size:30px;color:var(--navy);line-height:1;}\n  .progress-num span{font-size:15px;color:var(--ink-soft);font-family:'Pretendard';font-weight:500;}\n  .progress-track{height:10px;background:#e7e1d1;margin-top:10px;position:relative;overflow:hidden;}\n  .progress-fill{height:100%;background:var(--navy);width:0%;transition:width .25s ease;}\n  .resp-bar-row{display:flex;align-items:center;gap:8px;margin-bottom:8px;font-size:11.5px;}\n  .resp-bar-row:last-child{margin-bottom:0;}\n  .resp-bar-row .lbl{width:60px;flex:none;color:var(--ink);}\n  .resp-bar-row .track{flex:1;height:9px;background:#e7e1d1;position:relative;overflow:hidden;}\n  .resp-bar-row .fill{height:100%;}\n  .resp-bar-row .fill.yes{background:var(--good);}\n  .resp-bar-row .fill.no{background:var(--risk-hi);}\n  .resp-bar-row .fill.partial{background:var(--risk-mid);}\n  .resp-bar-row .fill.na{background:#9aa3b0;}\n  .resp-bar-row .cnt{width:24px;flex:none;text-align:right;font-family:'IBM Plex Mono',monospace;}\n  .domain-mini{margin-top:12px;}\n  .domain-mini .bar-label{display:flex;justify-content:space-between;font-size:12px;margin-bottom:4px;}\n  .domain-mini .bar-track{height:7px;background:#e7e1d1;}\n  .domain-mini .bar-fill.teal{background:var(--teal);}\n  .domain-mini .bar-fill.indigo{background:var(--indigo);}\n  .risk-flag-summary{display:flex;gap:10px;margin-top:14px;}\n  .risk-flag-summary .pill{\n    flex:1;padding:8px 10px;font-size:12px;border:1px solid var(--line);\n    display:flex;flex-direction:column;gap:2px;\n  }\n  .risk-flag-summary .pill b{font-family:'IBM Plex Mono',monospace;font-size:16px;}\n  .risk-flag-summary .pill.hi{background:var(--risk-hi-bg);color:var(--risk-hi);}\n  .risk-flag-summary .pill.mid{background:var(--risk-mid-bg);color:var(--risk-mid);}\n  .risk-flag-summary .pill.lo{background:#eef0ee;color:var(--ink-soft);}\n\n  .sr-bar-row{display:flex;align-items:center;gap:8px;margin-bottom:8px;font-size:11.5px;}\n  .sr-bar-row:last-child{margin-bottom:0;}\n  .sr-bar-row .lbl{width:60px;flex:none;color:var(--ink);}\n  .sr-bar-row .track{flex:1;height:9px;background:#e7e1d1;position:relative;overflow:hidden;}\n  .sr-bar-row .fill{height:100%;}\n  .sr-bar-row .fill.good{background:var(--good);}\n  .sr-bar-row .fill.mid{background:var(--risk-mid);}\n  .sr-bar-row .fill.poor{background:var(--risk-hi);}\n  .sr-bar-row .fill.none{background:#c7c1b1;}\n  .sr-bar-row .cnt{width:24px;flex:none;text-align:right;font-family:'IBM Plex Mono',monospace;}\n  .mismatch-note{\n    margin-top:12px;font-size:12.5px;color:var(--risk-hi);line-height:1.6;\n    background:var(--risk-hi-bg);padding:8px 10px;display:none;\n  }\n  .mismatch-note.show{display:block;}\n\n  .evidence-panel{padding:0 20px 22px;}\n  .evidence-panel h4{\n    font-size:12px;color:var(--ink-soft);letter-spacing:.03em;\n    font-family:'IBM Plex Mono',monospace;text-transform:uppercase;margin:0 0 10px;\n  }\n  .evidence-empty{font-size:12px;color:var(--ink-soft);border:1px dashed var(--line);padding:14px;text-align:center;}\n  .evi-review-item{\n    border:1px solid var(--good);border-left:4px solid var(--good);\n    padding:10px 14px;margin-bottom:8px;font-size:12px;background:var(--good-bg);\n  }\n  .evi-review-item .er-head{display:flex;justify-content:space-between;align-items:center;font-weight:700;margin-bottom:5px;color:var(--ink);}\n  .evi-review-item .er-code{font-family:'IBM Plex Mono',monospace;color:var(--steel);margin-right:6px;}\n  .evi-review-item .er-badge{\n    font-family:'IBM Plex Mono',monospace;font-size:9.5px;padding:2px 6px;border:1px solid var(--good);color:var(--good);background:var(--card);\n  }\n  .evi-review-item .er-evi{margin:4px 0 0;color:var(--ink);}\n  .evi-review-item .er-note{margin-top:4px;color:var(--ink-soft);font-style:italic;}\n\n  .missing-panel{padding:0 20px 22px;}\n  .groupware-panel h4{font-size:14px;margin:0 0 6px;color:var(--navy);font-family:'Pretendard';font-weight:700;}\n\n  /* ===== Toolbar: search / filter / jump / domain nav ===== */\n  .survey-toolbar{\n    position:sticky; top:0; z-index:50;\n    background:var(--navy); color:#f4efe2; padding:10px 44px;\n    box-shadow:0 2px 8px rgba(19,40,69,.25);\n  }\n  .toolbar-row{display:flex;gap:8px;flex-wrap:wrap;align-items:center;}\n  .toolbar-row + .toolbar-row{margin-top:8px;}\n  .searchBox-input{\n    flex:1; min-width:180px; border:1px solid rgba(228,199,138,.4); background:rgba(255,255,255,.08);\n    color:#f4efe2; padding:7px 10px; font-family:inherit; font-size:12.5px;\n  }\n  .searchBox-input::placeholder{color:#a9b4c8;}\n  .searchBox-input:focus{outline:none;border-color:var(--gold-l);background:rgba(255,255,255,.14);}\n  .jump-select{\n    border:1px solid rgba(228,199,138,.4); background:rgba(255,255,255,.08); color:#f4efe2;\n    padding:7px 8px; font-family:inherit; font-size:12px; max-width:260px;\n  }\n  .jump-select option{background:#ffffff; color:#1b2330;}\n  .filter-chip{\n    font-family:'IBM Plex Mono',monospace; font-size:11.5px; padding:6px 11px;\n    border:1px solid rgba(228,199,138,.5); background:transparent; color:#c9d2e2; cursor:pointer;\n  }\n  .filter-chip.active{background:var(--gold); border-color:var(--gold); color:var(--navy); font-weight:700;}\n  .domain-jump-row{display:flex;gap:6px;flex-wrap:wrap;}\n  .domain-jump-chip{\n    font-family:'IBM Plex Mono',monospace; font-size:11.5px; padding:4px 9px;\n    background:rgba(255,255,255,.08); border:1px solid rgba(228,199,138,.3); color:#c9d2e2; cursor:pointer;\n  }\n  .domain-jump-chip:hover{background:rgba(228,199,138,.18);}\n  .search-result-count{font-size:10.5px; color:#a9b4c8; white-space:nowrap;}\n  .zoom-ctrl-survey{\n    display:flex;align-items:center;gap:2px;background:rgba(255,255,255,.1);\n    border:1px solid rgba(228,199,138,.4);border-radius:6px;padding:2px;flex:none;\n  }\n  .zoom-ctrl-survey button{\n    font-family:'IBM Plex Mono',monospace;font-size:13px;font-weight:700;background:transparent;\n    border:none;color:#f4efe2;cursor:pointer;width:24px;height:24px;border-radius:4px;\n  }\n  .zoom-ctrl-survey button:hover{background:rgba(255,255,255,.18);}\n  .zoom-ctrl-survey .zoom-pct{font-family:'IBM Plex Mono',monospace;font-size:10.5px;color:#c9d2e2;min-width:34px;text-align:center;}\n  .item.js-hidden, .domain.js-all-hidden{display:none !important;}\n  .item.js-highlight{outline:2px solid var(--gold); outline-offset:2px;}\n\n  #backToTopBtn{\n    position:fixed; right:22px; bottom:22px; z-index:60;\n    width:42px; height:42px; border-radius:50%; border:none;\n    background:var(--navy); color:#f4efe2; font-size:16px; cursor:pointer;\n    box-shadow:0 3px 10px rgba(19,40,69,.4); display:none;\n  }\n  #backToTopBtn:hover{background:var(--navy-2);}\n  #backToTopBtn.show{display:block;}\n\n  @media print{\n    .survey-toolbar, #backToTopBtn{display:none !important;}\n    .item.js-hidden, .domain.js-all-hidden{display:block !important;}\n  }\n\n  .missing-panel h4{\n    font-size:12px;color:var(--ink-soft);letter-spacing:.03em;\n    font-family:'IBM Plex Mono',monospace;text-transform:uppercase;margin:0 0 10px;\n  }\n  .missing-empty{font-size:12px;color:var(--good);border:1px dashed var(--good);padding:14px;text-align:center;background:var(--good-bg);}\n  .missing-all-done{font-size:12.5px;color:var(--good);border:1px solid var(--good);padding:14px;text-align:center;background:var(--good-bg);font-weight:700;}\n  .missing-item{\n    border:1px solid var(--line);border-left:4px solid var(--risk-mid);\n    padding:9px 14px;margin-bottom:7px;font-size:12px;\n  }\n  .missing-item .mi-head{display:flex;justify-content:space-between;align-items:center;font-weight:700;margin-bottom:3px;}\n  .missing-item .mi-code{font-family:'IBM Plex Mono',monospace;color:var(--steel);margin-right:6px;}\n  .missing-item .mi-what{color:var(--ink-soft);font-weight:400;font-size:11.3px;}\n\n  .flagged-panel{padding:0 20px 20px;}\n  .flagged-panel h4{\n    font-size:12px;color:var(--ink-soft);letter-spacing:.03em;\n    font-family:'IBM Plex Mono',monospace;text-transform:uppercase;margin:0 0 10px;\n  }\n  .flagged-empty{font-size:12px;color:var(--ink-soft);border:1px dashed var(--line);padding:14px;text-align:center;}\n  .flagged-item{\n    border:1px solid var(--line);border-left:4px solid var(--risk-mid);\n    padding:10px 14px;margin-bottom:8px;font-size:12px;\n  }\n  .flagged-item.risk-상{border-left-color:var(--risk-hi);}\n  .flagged-item.risk-하{border-left-color:var(--ink-soft);}\n  .flagged-item .fi-head{display:flex;justify-content:space-between;align-items:center;font-weight:700;margin-bottom:5px;}\n  .flagged-item .fi-code{font-family:'IBM Plex Mono',monospace;color:var(--steel);margin-right:6px;}\n  .flagged-item .fi-badge{\n    font-family:'IBM Plex Mono',monospace;font-size:9.5px;padding:2px 6px;border:1px solid currentColor;\n  }\n  .flagged-item.risk-상 .fi-badge{color:var(--risk-hi);}\n  .flagged-item.risk-중 .fi-badge{color:var(--risk-mid);}\n  .flagged-item.risk-하 .fi-badge{color:var(--ink-soft);}\n  .flagged-item .fi-badge.mismatch{background:var(--navy);color:#fff!important;border-color:var(--navy);}\n  .flagged-item .fi-sr{font-size:11.5px;margin-top:4px;color:var(--ink-soft);}\n  .flagged-item ul{margin:4px 0 0;padding-left:16px;color:var(--ink-soft);}\n  .flagged-item li{margin:2px 0;}\n  .flagged-item li b{color:var(--risk-hi);}\n\n  /* ===== Domain section ===== */\n  .domain{\n    padding:8px 44px 6px;\n  }\n  .domain-head{\n    display:flex;align-items:center;gap:14px;\n    margin:34px 0 18px;\n    padding-bottom:10px;\n    border-bottom:2px solid var(--navy);\n  }\n  .domain-num{\n    font-family:'Pretendard';font-weight:800;letter-spacing:-0.01em;font-size:26px;\n    color:#fff;width:44px;height:44px;flex:none;\n    display:flex;align-items:center;justify-content:center;\n  }\n  .domain[data-tone=\"teal\"] .domain-num{background:var(--teal);}\n  .domain[data-tone=\"indigo\"] .domain-num{background:var(--indigo);}\n  .domain-head h2{\n    font-family:'Pretendard';font-weight:700;letter-spacing:-0.01em;font-size:19px;margin:0 0 3px;color:var(--navy);\n  }\n  .domain-head .ref{font-size:12px;color:var(--ink-soft);font-family:'IBM Plex Mono',monospace;}\n\n  /* ===== Item card ===== */\n  .item{\n    background:var(--card);\n    border:1px solid var(--line);\n    margin-bottom:14px;\n    break-inside:avoid;\n    page-break-inside:avoid;\n  }\n  .item-head{\n    display:flex;align-items:flex-start;gap:12px;\n    padding:14px 18px 10px;\n  }\n  .item-no{\n    font-family:'IBM Plex Mono',monospace;font-weight:600;font-size:12px;\n    color:#fff;background:var(--steel);\n    padding:3px 8px;flex:none;margin-top:2px;\n  }\n  .domain[data-tone=\"teal\"] .item-no{background:var(--teal);}\n  .domain[data-tone=\"indigo\"] .item-no{background:var(--indigo);}\n  .item-title-wrap{flex:1;}\n  .item-title{font-weight:700;font-size:16.5px;color:var(--ink);}\n  .item-desc{font-size:13.5px;color:var(--ink-soft);margin-top:5px;line-height:1.65;}\n  .item-tags{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end;max-width:220px;align-items:center;}\n  .tag{\n    font-size:9.5px;font-family:'IBM Plex Mono',monospace;\n    padding:3px 7px;border:1px solid var(--line);color:var(--ink-soft);white-space:nowrap;\n  }\n  .tag.risk-hi{background:var(--risk-hi-bg);color:var(--risk-hi);border-color:var(--risk-hi);}\n  .tag.dept-tag{background:var(--indigo-bg);color:var(--indigo);border-color:var(--indigo);white-space:nowrap;}\n\n  table.check-tbl{\n    width:100%;border-collapse:collapse;font-size:13.5px;\n    border-top:1px solid var(--line);\n  }\n  table.check-tbl td, table.check-tbl th{\n    border-bottom:1px solid #ece7d9;\n    padding:9px 10px;\n    vertical-align:middle;\n  }\n  table.check-tbl th{\n    background:#f1ede1;font-size:11.5px;color:var(--ink-soft);\n    text-align:center;font-weight:600;letter-spacing:.02em;\n  }\n  table.check-tbl td.q{color:var(--ink);line-height:1.6;}\n  /* 항목 카드 안에서 두 가지 서로 다른 번호 체계가 섞여 있어 헷갈린다는 지적에 따라,\n     \"채워진 배지 = 이 항목을 채우는 4단계(상위)\" / \"테두리만 있는 배지 = 그 안의 개별 체크포인트(하위)\"로\n     시각 언어를 명확히 분리. 크기·명암비도 함께 키워 가독성을 높였다. */\n  .item-step-num{\n    display:inline-flex; align-items:center; justify-content:center; flex:none;\n    min-width:26px; height:26px; padding:0 5px; border-radius:6px; background:var(--navy);\n    color:#ffffff; font-family:'IBM Plex Mono',monospace; font-size:14px; font-weight:800;\n    margin-right:7px; vertical-align:middle; box-shadow:0 1px 3px rgba(19,40,69,.35);\n  }\n  .cp-row-num{\n    display:inline-flex; align-items:center; justify-content:center; flex:none;\n    width:23px; height:23px; border-radius:50%; background:#fff; border:2px solid var(--navy);\n    color:var(--navy); font-family:'IBM Plex Mono',monospace; font-size:12px; font-weight:800; margin-right:6px;\n  }\n  table.check-tbl td.opt{text-align:center;width:44px;}\n  input[type=radio].resp{\n    width:15px;height:15px;accent-color:var(--navy-2);cursor:pointer;\n  }\n  /* [수정] 이전에는 align-items:start 때문에 왼쪽(증빙)·오른쪽(비고) 칸이 각자 내용 길이만큼만\n     따로 늘어나, 체크박스를 몇 개 더 체크하거나 증빙 내용을 길게 적어도 오른쪽 비고 칸은 짧은 채로\n     남아 바닥선이 안 맞고 지저분해 보였다. align-items:start를 없애 그리드 기본 동작(두 칸이 항상\n     더 긴 쪽 높이에 맞춰짐)으로 되돌리고, 아래 JS(syncItemFootHeight)로 두 입력창 자체의 높이도\n     서로 맞춰 실제로 \"왼쪽이 늘어나는 만큼 오른쪽도 늘어나 보이게\" 만든다. */\n  .item-foot{\n    display:grid;grid-template-columns:1.3fr 1fr;\n    border-top:1px solid var(--line);\n  }\n  .item-foot .cell{padding:12px 18px 16px;font-size:12.5px;display:flex;flex-direction:column;}\n  .item-foot .cell + .cell{border-left:1px solid var(--line);}\n  .item-foot label{\n    display:block;color:var(--ink-soft);font-size:11.5px;margin-bottom:7px;line-height:1.5;\n    font-family:'IBM Plex Mono',monospace;letter-spacing:.03em;\n  }\n  .item-foot .evi-list{flex:none;}\n  .item-foot .evi-purpose-hint{flex:none;}\n  .item-foot .note-input, .item-foot .evi-custom-input{flex:none;}\n  @media (max-width:760px){\n    .item-foot{grid-template-columns:1fr;}\n    .item-foot .cell + .cell{border-left:none;border-top:1px solid var(--line);}\n  }\n  .evi-list{font-size:12.5px;color:var(--ink);}\n  .evi-item{margin-bottom:8px;}\n  .evi-item:last-child{margin-bottom:0;}\n  .evi-item label{display:flex;align-items:center;gap:6px;cursor:pointer;}\n  .evi-box{width:13px;height:13px;accent-color:var(--steel);cursor:pointer;flex:none;}\n  .evi-filename-hint{\n    margin:6px 0 0 21px;padding:8px 10px;background:var(--indigo-bg);border:1px solid var(--indigo);border-radius:4px;\n    font-family:'IBM Plex Mono',monospace;font-size:11.5px;color:var(--navy);font-weight:600;\n    word-break:break-all;line-height:1.6;\n  }\n  .evi-filename-hint b{color:var(--indigo);font-weight:800;}\n  .evi-purpose-hint{\n    margin:0 0 8px;padding:7px 10px;background:var(--teal-bg);border:1px solid var(--teal);border-radius:4px;\n    font-size:11.8px;color:var(--ink);line-height:1.6;\n  }\n  .note-input{\n    width:100%;border:1px solid #c7c1b1;background:#fffdf8;min-height:64px;box-sizing:border-box;\n    font-family:inherit;font-size:12.5px;padding:8px 9px;margin-top:2px;resize:vertical;line-height:1.55;\n  }\n\n  .owner-check, .fam-check{\n    border-top:1px solid var(--line);background:#f5f1e6;padding:11px 18px 13px;\n  }\n  .owner-check > label, .fam-check > label{\n    display:block;color:var(--ink-soft);font-size:11.5px;margin-bottom:8px;\n    font-family:'IBM Plex Mono',monospace;letter-spacing:.03em;\n  }\n  .owner-options, .fam-options{display:flex;gap:10px;flex-wrap:wrap;align-items:center;}\n  .owner-opt, .fam-opt{\n    display:flex;align-items:center;gap:6px;font-size:12px;cursor:pointer;\n    padding:7px 12px;border:1.4px solid var(--line);background:var(--card);color:var(--ink-soft);\n  }\n  .owner-opt input, .fam-opt input{width:14px;height:14px;cursor:pointer;}\n  .owner-opt.on{border-color:var(--navy-2);background:var(--indigo-bg);color:var(--navy-2);font-weight:700;}\n  .fam-opt.on.high{border-color:var(--good);background:var(--good-bg);color:var(--good);font-weight:700;}\n  .fam-opt.on.mid{border-color:var(--risk-mid);background:var(--risk-mid-bg);color:var(--risk-mid);font-weight:700;}\n  .fam-opt.on.low{border-color:var(--risk-hi);background:var(--risk-hi-bg);color:var(--risk-hi);font-weight:700;}\n  .owner-dept-input{\n    border:1px solid #c7c1b1;background:#fffdf8;font-family:inherit;font-size:12px;padding:6px 8px;\n    width:220px;display:none;\n  }\n  .owner-dept-input.dept-input-required{\n    border:1.6px solid var(--risk-hi);background:var(--risk-hi-bg);\n    box-shadow:0 0 0 2px rgba(162,59,46,.12);\n  }\n  .owner-dept-input.dept-input-required::placeholder{color:var(--risk-hi);font-weight:600;}\n  .owner-person-input{\n    border:1px solid #c7c1b1;background:#fffdf8;font-family:inherit;font-size:12px;padding:6px 8px;\n    width:190px;margin-left:8px;\n  }\n  .owner-person-label{font-size:11.5px;color:var(--ink-soft);margin-left:8px;margin-right:4px;}\n  .owner-person-row{\n    display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-top:10px;padding:9px 12px;\n    background:var(--good-bg);border:1px solid #b7d4c4;border-radius:6px;\n  }\n  .owner-person-row .opr-label{font-size:12.5px;font-weight:700;color:var(--navy);flex:none;}\n  .owner-person-row .opr-sub{font-size:11px;color:var(--ink-soft);flex-basis:100%;margin-top:-4px;}\n  .owner-person-row .owner-person-input{margin-left:0;width:220px;flex:1 1 200px;}\n  .owner-warn-note{\n    font-size:11.5px;color:#8a3b1f;background:#fdf2e9;border:1px solid #edcba8;border-radius:5px;\n    padding:9px 12px;margin-top:9px;line-height:1.65;transition:all .15s;\n  }\n  .owner-warn-note.active{\n    font-size:12.5px;font-weight:700;color:#fff;background:var(--risk-hi);border:2px solid #7a291f;border-radius:6px;\n    padding:12px 14px;margin-top:10px;line-height:1.7;box-shadow:0 0 0 4px rgba(162,59,46,.18);\n  }\n  .owner-warn-note.active b{color:#ffe9c2;}\n  .cp-skip-notice{\n    display:none;background:#fdecea;border:1px solid #e0b4ae;color:#a23b2e;padding:10px 14px;\n    border-radius:6px;font-size:12.5px;font-weight:700;margin:12px 0 0;\n  }\n  .item.other-dept-skip .cp-skip-notice{display:block;}\n  .item.other-dept-skip .fam-check,\n  .item.other-dept-skip table.check-tbl,\n  .item.other-dept-skip .item-foot,\n  .item.other-dept-skip .self-rating{\n    opacity:.42;pointer-events:none;filter:grayscale(.3);\n  }\n  .law-note{font-size:10.8px;color:var(--steel);margin-top:5px;font-family:'IBM Plex Mono',monospace;}\n\n  .self-rating{\n    border-top:1px solid var(--line);background:#faf8f0;padding:12px 18px 14px;\n  }\n  .self-rating > label{\n    display:block;color:var(--ink-soft);font-size:11.5px;margin-bottom:8px;\n    font-family:'IBM Plex Mono',monospace;letter-spacing:.03em;\n  }\n  .sr-options{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:9px;}\n  .sr-opt{\n    display:flex;align-items:center;gap:6px;font-size:12px;cursor:pointer;\n    padding:7px 12px;border:1.4px solid var(--line);background:var(--card);\n    color:var(--ink-soft);transition:all .12s;\n  }\n  .sr-opt input{width:14px;height:14px;cursor:pointer;}\n  .sr-opt.good.on{border-color:var(--good);background:var(--good-bg);color:var(--good);font-weight:700;}\n  .sr-opt.mid.on{border-color:var(--risk-mid);background:var(--risk-mid-bg);color:var(--risk-mid);font-weight:700;}\n  .sr-opt.poor.on{border-color:var(--risk-hi);background:var(--risk-hi-bg);color:var(--risk-hi);font-weight:700;}\n  .sr-note{\n    width:100%;border:1px solid #c7c1b1;background:#fffdf8;\n    font-family:inherit;font-size:11.5px;padding:7px 9px;resize:vertical;\n  }\n  .sr-hint{font-size:11.5px;color:var(--ink-soft);margin-top:5px;line-height:1.6;}\n\n  .domain-subtotal{\n    text-align:right;font-size:12px;color:var(--ink-soft);\n    margin:-4px 0 26px;font-family:'IBM Plex Mono',monospace;\n  }\n\n  /* ===== Sign-off ===== */\n  .signoff{\n    margin:30px 44px 0;\n    border:1px solid var(--line);background:var(--card);\n  }\n  .signoff-head{\n    background:var(--navy);color:#f4efe2;padding:10px 18px;font-size:12.5px;\n    font-family:'Pretendard';font-weight:700;letter-spacing:-0.01em;letter-spacing:.02em;\n  }\n  .signoff-grid{display:grid;grid-template-columns:repeat(3,1fr);}\n  .signoff-grid .cell{padding:16px 18px;border-right:1px solid var(--line);}\n  .signoff-grid .cell:last-child{border-right:none;}\n  .signoff-grid label{font-size:11.5px;color:var(--ink-soft);font-family:'IBM Plex Mono',monospace;}\n  .sign-space{height:44px;border-bottom:1px solid #9aa3b0;margin-top:16px;}\n\n  footer{\n    padding:22px 44px 40px;\n    font-size:11.5px;color:var(--ink-soft);\n    display:flex;justify-content:space-between;\n  }\n\n  .no-print{}\n  @media print{\n    body{background:#fff;}\n    .page-shell{box-shadow:none;margin:0;max-width:none;}\n    .domain{page-break-before:always;}\n    .domain:first-of-type{page-break-before:auto;}\n    .item{page-break-inside:avoid;}\n    .dash{page-break-inside:avoid;page-break-after:always;}\n    .dash-btn{display:none;}\n    @page{size:A4;margin:14mm 12mm;}\n  }\n  @media (max-width:640px){\n    .hero,.info-bar,.domain,.dash,.signoff,footer{padding-left:18px;padding-right:18px;}\n    .info-bar,.fill-grid,.dash-body,.signoff-grid{grid-template-columns:1fr;}\n  }\n</style>\n</head>\n<body>\n<div class=\"page-shell\">\n\n  <div class=\"hero\">\n    <div class=\"eyebrow\">IT AUDIT · PRE-INTERVIEW QUESTIONNAIRE</div>\n    <h1>__H1_LINE1__<br>__H1_LINE2__</h1>\n    <div class=\"sub\">__SUB_INTRO__</div>\n    __AUDIT_CONTEXT__\n    __SHARED_BANNER__\n    <div class=\"hero-meta\">\n      <div>대상 영역<strong>__META_DOMAIN__</strong></div>\n      <div>총 점검항목<strong>__TOTAL_ITEMS__개</strong></div>\n      <div>세부 체크포인트<strong>__TOTAL_CP__개</strong></div>\n      <div>준거기준<strong>__META_REFS__</strong></div>\n      <div>회신 기한<strong style=\"color:var(--gold-l);\">__DUE_DATE_DISPLAY__</strong></div>\n    </div>\n  </div>\n\n  <div class=\"info-bar\">\n    <div class=\"info-guide-btn-row\">\n      <h3 style=\"margin:0;\">📝 작성 안내</h3>\n      <button type=\"button\" class=\"info-guide-open-btn\" onclick=\"openWritingGuideWindow()\">🖼 작성 가이드 새 창으로 열기 (참고하며 작성)</button>\n    </div>\n    <div class=\"wg-flow\">\n      <div class=\"wg-step\"><b>① 담당여부</b>내 업무인지 표시(타부서/모름도 정상 응답)</div>\n      <div class=\"wg-arrow\">→</div>\n      <div class=\"wg-step\"><b>② 숙지도</b>이 업무를 얼마나 알고 있는지</div>\n      <div class=\"wg-arrow\">→</div>\n      <div class=\"wg-step\"><b>③ 체크포인트</b>__SCALE_HINT__ 중 선택</div>\n      <div class=\"wg-arrow\">→</div>\n      <div class=\"wg-step\"><b>④ 자체평가</b>실제 이행 수준에 대한 본인 의견</div>\n      <div class=\"wg-arrow\">→</div>\n      <div class=\"wg-step\" style=\"border-color:var(--good);\"><b>⑤ 제출</b>하단 [CSV/JSON 다운로드] → 감사역 전달</div>\n    </div>\n    <div class=\"response-key-compact\" id=\"response-key-container\"></div>\n    <details class=\"info-detail-toggle\">\n      <summary>📄 문구로 자세히 읽기 (선택)</summary>\n      <ol>\n        <li>__INFO_BULLET1__</li>\n        <li>각 항목은 <b>① 담당여부 → ② 숙지도 → ③ 세부 체크포인트 → ④ 자체평가</b> 순서로 응답합니다. 담당 업무가 아니거나 잘 모르는 항목이라도 \"타 부서 담당\"/\"잘 모름\"으로 사실대로 표시해 주십시오 — 이는 오답이 아니라 감사역이 인터뷰 대상과 방향을 정확히 잡는 데 필요한 정보입니다.</li>\n        <li>③ 세부 체크포인트는 실제 이행 현황을 <b>__SCALE_HINT__</b> 중 하나로 응답해 주십시오. (화면에서 직접 응답 가능, 인쇄 후 수기 작성도 가능)</li>\n        <li>부정적인 응답으로 표시한 항목은 비고란에 사유를, ④ 자체평가란에는 해당 통제를 실제로 얼마나 잘 이행하고 있다고 생각하시는지 본인의 의견과 근거를 적어주십시오. \"잘하고 있음\"으로 평가하신 항목은 감사역이 증빙 위주로 우선 검토합니다.</li>\n        <li>제출 가능한 증빙자료명을 체크하시면, 현장 인터뷰 시 해당 자료를 지참·공유해 주시기 바랍니다. 체크하면 그 자리에 <b>권장 저장 파일명</b>이 자동으로 표시되니, 증빙 파일(스캔본·캡처 등)을 저장하실 때 그 이름을 그대로 사용해 주십시오. (상단 \"수검부서\"란을 먼저 입력하면 파일명에 반영됩니다)</li>\n        <li><b>증빙자료 자유입력란(목록 아래)</b>과 <b>비고란(맨 아래)</b>은 서로 다른 용도입니다 — <b>증빙자료 자유입력란</b>은 목록에 없는 자료명이거나, 제출할 증빙이 없거나 다른 방식(예: 구두 확인, 현장 시연)으로 대체되는 경우 그 사정을 적는 곳입니다. 이 내용은 감사역이 그대로 확인하니, 자료가 없다면 없다고, 다른 것으로 대체한다면 어떻게 대체하는지 적어주시면 인터뷰 때 다시 여쭤보지 않아도 됩니다. <b>비고란</b>은 응답이 \"아니오\"·\"부분\"일 때의 사유나 개선 계획을 적는 곳으로, 증빙 여부와는 별개입니다.</li>\n        <li>화면 상단의 <b>\"인터뷰 조율 참고사항\"</b>은 선택 입력이며, 감사기간 중 인터뷰가 필요할 경우 참석이 어려운 날짜·시간대나 협조 요청사항을 미리 적어두는 곳입니다(예: \"매주 화요일 오전 회의로 어려움\", \"화상보다 유선 선호\"). 되는 시간을 나열하기보다 <b>안 되는 시간·조건만 간단히</b> 적어주시면 감사역이 일정을 잡을 때 더 빠르게 확인할 수 있습니다. 특별한 제약이 없으면 비워두셔도 됩니다.</li>\n        <li>__INFO_BULLET6__</li>\n        <li>__INFO_BULLET7__</li>\n      </ol>\n    </details>\n  </div>\n\n  <div class=\"fill-grid\">\n    <div class=\"fill-cell\"><label>수검부서</label><input type=\"text\" id=\"f-dept\" placeholder=\"__DEPT_PLACEHOLDER__\" value=\"__DEPT_PREFILL__\"></div>\n    <div class=\"fill-cell\"><label>작성자 / 직책</label><input type=\"text\" id=\"f-author\" placeholder=\"예) 홍길동 팀장\"></div>\n    <div class=\"fill-cell\"><label>작성일</label><input type=\"date\" id=\"f-date\"></div>\n    <div class=\"fill-cell\"><label>회신 기한 (감사자 지정)</label><div id=\"f-dueDateDisplay\" style=\"font-size:13px;color:var(--risk-hi);font-weight:700;padding:2px 0;\">__DUE_DATE_DISPLAY__</div></div>\n  </div>\n  <div class=\"interview-avail-row\">\n    <label>👤 인터뷰 담당자 <span style=\"color:var(--risk-hi);font-weight:700;\">(필수 — 인터뷰 대상 확정 시 필요)</span> — 실제로 감사역과 인터뷰에 응해주실 담당자 성명·직책을 적어주세요. 여러 명이면 쉼표로 구분해 모두 적어주십시오. 설문 작성자와 다를 수 있습니다.</label>\n    <input type=\"text\" id=\"f-interviewContact\" placeholder=\"예) 홍길동 과장, 김철수 대리\">\n  </div>\n  <div class=\"interview-avail-row\">\n    <label>🗓 인터뷰 조율 참고사항 (선택 입력) — 감사기간 중 간단한 인터뷰가 진행될 수 있습니다. <b>참석이 어려운 날짜·시간대</b>(정기 회의, 휴가, 출장 등)나 인터뷰 진행 시 <b>협조를 요청할 사항</b>(예: 화상 대신 유선 희망 등)이 있다면 적어주세요. 특별한 제약이 없으면 비워두셔도 됩니다.</label>\n    <input type=\"text\" id=\"f-interviewAvail\" placeholder=\"예) 매주 화요일 오전은 회의로 어려움 / 8월 25~27일 휴가 / 화상보다 유선 통화를 선호합니다\">\n  </div>\n\n  <div class=\"no-print\" id=\"draftRestoreBanner\" style=\"display:none;margin:16px 44px 0;background:#eef0f6;border:1px solid #c9d0e0;border-radius:6px;padding:10px 16px;font-size:12.5px;color:var(--ink);display:none;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;\">\n    <span>💾 <b>이전에 작성 중이던 내용을 이어서 불러왔습니다</b> (<span id=\"draftRestoreTime\"></span> 자동저장분). 창을 닫았다가 다시 열어도 이 브라우저에서는 계속 이어서 작성할 수 있습니다.</span>\n    <button type=\"button\" class=\"dash-btn\" style=\"background:var(--risk-hi);border-color:var(--risk-hi);color:#fff;\" id=\"discardDraftBtn\">이 임시저장 지우고 새로 시작</button>\n  </div>\n\n  <!-- ============ WRITER PROGRESS PANEL ============ -->\n  <div class=\"dash no-print\" id=\"dash\">\n    <div class=\"dash-head\">\n      <h2>작성 진행 현황</h2>\n      <div class=\"dash-actions\">\n        <button class=\"dash-btn\" onclick=\"window.print()\">인쇄 / PDF 저장</button>\n        <button class=\"dash-btn\" onclick=\"downloadCSV()\">결과 CSV 다운로드</button>\n        <button class=\"dash-btn\" onclick=\"downloadJSON()\">결과 JSON 다운로드</button>\n        <button class=\"dash-btn\" onclick=\"openSummaryInfographic()\">📊 요약·전체 리뷰 보기</button>\n        <button class=\"dash-btn\" onclick=\"toggleGroupwarePanel()\">📋 그룹웨어 협조문용 요약표</button>\n        <button class=\"dash-btn\" onclick=\"document.getElementById('resumeJsonFileInput').click()\">📥 저장한 JSON 불러와 이어작성</button>\n        <button class=\"dash-btn\" onclick=\"resetAll()\">초기화</button>\n        <input type=\"file\" id=\"resumeJsonFileInput\" accept=\".json\" style=\"display:none;\">\n      </div>\n    </div>\n    <div class=\"dash-body\" style=\"grid-template-columns:1fr;\">\n      <div class=\"dash-card\">\n        <h4>전체 응답 진행률</h4>\n        <div class=\"progress-num\"><span id=\"ans-count\">0</span> / __TOTAL_CP__ <span>체크포인트 응답</span></div>\n        <div class=\"progress-track\"><div class=\"progress-fill\" id=\"progress-fill\"></div></div>\n        <div id=\"domain-mini-container\"></div>\n      </div>\n    </div>\n    <div class=\"groupware-panel no-print\" id=\"groupwarePanel\" style=\"display:none;padding:0 20px 22px;\">\n      <h4>📋 그룹웨어 협조문용 요약표</h4>\n      <p style=\"font-size:11.5px;color:var(--ink-soft);margin:0 0 10px;line-height:1.6;\">이 설문 응답을 감사부서에 회신할 때, 협조문·보고서 본문에 그대로 붙여넣을 수 있는 표입니다. 응답을 마친 뒤 [요약표 새로고침]을 눌러 최신 상태로 만들고, [표 복사하기]로 클립보드에 담아 그룹웨어 문서에 붙여넣으세요 (Ctrl+V).</p>\n      <div class=\"round-controls\" style=\"display:flex;gap:8px;margin-bottom:12px;flex-wrap:wrap;\">\n        <button class=\"dash-btn\" style=\"background:var(--navy);border-color:var(--navy);color:#f4efe2;\" onclick=\"buildGroupwareSummary()\">요약표 새로고침</button>\n        <button class=\"dash-btn\" id=\"gwCopyBtn\" onclick=\"copyGroupwareSummary()\" disabled>표 복사하기</button>\n        <button class=\"dash-btn\" id=\"gwDownloadBtn\" onclick=\"downloadGroupwareSummary()\" disabled>HTML 파일로 다운로드</button>\n      </div>\n      <div id=\"groupwareSummaryPreview\" style=\"border:1px solid var(--line);background:#fff;padding:12px;overflow-x:auto;\"></div>\n    </div>\n    <details class=\"missing-panel\">\n      <summary><h4 style=\"display:inline;margin:0;cursor:pointer;\">아직 작성하지 않은 항목 (누락 확인용) <span id=\"missing-count-badge\" class=\"mono\" style=\"font-size:11px;color:var(--risk-mid);\"></span></h4><span style=\"font-size:11px;color:var(--ink-soft);font-weight:400;margin-left:8px;\">— 필요할 때만 펼쳐보세요. 화면이 넓으면 왼쪽 \"빠른 메뉴\"에서도 항목별 작성완료/작성중/미작성 표시로 바로 확인할 수 있습니다.</span></summary>\n      <div id=\"missing-list\" style=\"margin-top:10px;\">\n        <div class=\"missing-empty\">아직 응답을 시작하지 않았습니다. 작성을 진행하면 미완료 항목이 여기에 표시됩니다.</div>\n      </div>\n    </details>\n  </div>\n\n  <div class=\"survey-toolbar no-print\" id=\"surveyToolbar\">\n    <div class=\"toolbar-row\">\n      <input type=\"text\" class=\"searchBox-input\" id=\"searchBox\" placeholder=\"🔍 키워드로 항목 검색 (제목·설명·체크포인트)\">\n      <select class=\"jump-select\" id=\"jumpSelect\"><option value=\"\">항목 번호로 바로가기…</option></select>\n      <span class=\"search-result-count\" id=\"searchResultCount\"></span>\n      <div class=\"zoom-ctrl-survey\" title=\"화면 확대/축소\">\n        <button id=\"zoomOutBtn\" type=\"button\">−</button>\n        <span class=\"zoom-pct\" id=\"zoomPctLabel\">100%</span>\n        <button id=\"zoomInBtn\" type=\"button\">+</button>\n        <button id=\"zoomResetBtn\" type=\"button\" title=\"100%로 초기화\">↺</button>\n      </div>\n    </div>\n    <div class=\"toolbar-row\">\n      <button class=\"filter-chip active\" data-filter=\"all\">전체 보기</button>\n      <button class=\"filter-chip\" data-filter=\"notstarted\">미작성 항목만</button>\n      <button class=\"filter-chip\" data-filter=\"inprogress\">작성중인 항목만</button>\n      <button class=\"filter-chip\" data-filter=\"complete\">완료 항목만</button>\n      <button class=\"filter-chip\" data-filter=\"risk-상\">위험도 상만</button>\n      <button class=\"filter-chip\" data-filter=\"risk-중\">위험도 중만</button>\n      <button class=\"filter-chip\" data-filter=\"risk-하\">위험도 하만</button>\n    </div>\n    <div class=\"toolbar-row domain-jump-row\" id=\"domainJumpRow\"></div>\n  </div>\n\n  <div class=\"side-navmap no-print\" id=\"sideNavMap\"></div>\n  <div id=\"quickMenuBackdrop\" class=\"no-print\"></div>\n  <button id=\"quickMenuFab\" class=\"no-print\" type=\"button\">☰ 빠른 메뉴</button>\n\n  <div id=\"allCompleteModal\" class=\"no-print\" style=\"display:none;\">\n    <div class=\"acm-card\">\n      <div class=\"acm-emoji\">🎉</div>\n      <h3>모든 문항 작성을 완료했습니다!</h3>\n      <p>수고하셨습니다. 이제 결과 파일(JSON)을 내려받아, 그룹웨어 협조문(첨부파일)으로 IT감사팀에 보내주시면 됩니다.</p>\n      <div class=\"acm-actions\">\n        <button type=\"button\" class=\"acm-primary-btn\" onclick=\"downloadJSONFromModal()\">⬇ 결과 JSON 다운로드</button>\n        <button type=\"button\" class=\"acm-secondary-btn\" onclick=\"closeAllCompleteModal()\">계속 검토하기</button>\n      </div>\n      <div class=\"acm-hint\">\n        ✏ <b>수정이 더 필요하다면?</b> 이 창을 닫고 해당 항목을 고친 뒤, 다시 이 안내가 뜨면(또는 아무 때나 하단 버튼으로) JSON을 다시 받아 보내주시면 됩니다. 예전에 받은 파일은 지우지 않아도 되며, 가장 마지막에 보낸 파일이 최신본으로 인정됩니다.\n      </div>\n    </div>\n  </div>\n\n  __DOMAINS_HTML__\n\n  <button id=\"backToTopBtn\" class=\"no-print\" title=\"맨 위로\">▲</button>\n\n  <footer>\n    <span>__FOOTER_LABEL__</span>\n    <span class=\"mono\">문서 형식: 응답형 설문 (진행률·누락확인 전용, 분석은 감사역 시스템에서 수행)</span>\n  </footer>\n\n</div>\n\n<script>\nconst TOTAL_CP = __TOTAL_CP__;\nlet DOM_TOTALS = {};\nlet SCALE_OPTIONS = []; // [{value, tier}] auto-detected from rendered radios, in first-seen order\nconst TIER_COLOR = {good:'var(--good)', bad:'var(--risk-hi)', neutral:'var(--risk-mid)', na:'#9aa3b0'};\nconst TIER_LABEL = {good:'양호 — 이행이 잘 되고 있음', bad:'개선 필요 — 이행되지 않거나 미흡함', neutral:'보통 — 부분적으로 이행됨', na:'해당없음 — 조직 특성상 적용되지 않음'};\n\nfunction initDashboard(){\n  const container = document.getElementById('domain-mini-container');\n  const seen = {};\n  document.querySelectorAll('.domain').forEach(domEl => {\n    const code = domEl.dataset.domain;\n    const tone = domEl.dataset.tone;\n    const h2 = domEl.querySelector('.domain-head h2');\n    const title = h2 ? h2.textContent.trim() : code;\n    const cpCount = domEl.querySelectorAll('tr.cp-row').length;\n    if(seen[code] || cpCount === 0) return;\n    seen[code] = true;\n    DOM_TOTALS[code] = cpCount;\n    const wrap = document.createElement('div');\n    wrap.className = 'domain-mini';\n    wrap.innerHTML = '<div class=\"bar-label\"><span>' + code + ' · ' + title + '</span>'\n      + '<span id=\"dom-' + code + '-frac\" class=\"mono\">0/' + cpCount + '</span></div>'\n      + '<div class=\"bar-track\"><div class=\"bar-fill ' + tone + '\" id=\"dom-' + code + '-fill\" style=\"width:0%;height:100%;\"></div></div>';\n    container.appendChild(wrap);\n  });\n\n  // Auto-detect the response scale from whatever radios were rendered into this survey,\n  // and populate the plain-language legend (no live analytics chart — this document is\n  // for the respondent; response distribution analysis happens only in the auditor's hub).\n  const seenVals = new Set();\n  document.querySelectorAll('input.resp').forEach(el => {\n    if(!seenVals.has(el.value)){\n      seenVals.add(el.value);\n      SCALE_OPTIONS.push({value: el.value, tier: el.dataset.tier || 'neutral'});\n    }\n  });\n\n  const keyContainer = document.getElementById('response-key-container');\n  keyContainer.innerHTML = '<span class=\"rk-label\">응답 기준:</span>' + SCALE_OPTIONS.map(o =>\n    '<span class=\"k-row\"><span class=\"chip' + (o.tier==='na'?' na':'') + '\" style=\"border-color:' + (TIER_COLOR[o.tier]||TIER_COLOR.neutral) + ';color:' + (TIER_COLOR[o.tier]||TIER_COLOR.neutral) + ';\">●</span> <b>' + o.value + '</b>=' + (TIER_LABEL[o.tier]||'') + '</span>'\n  ).join('');\n}\n\nfunction collectStats(){\n  const items = document.querySelectorAll('.item');\n  let answered = 0;\n  const domAnswered = {};\n  Object.keys(DOM_TOTALS).forEach(k => domAnswered[k] = 0);\n  const incomplete = [];\n\n  items.forEach(item => {\n    const code = item.dataset.code;\n    const domain = item.dataset.domain;\n    const title = item.dataset.title;\n    const missingParts = [];\n\n    const ownChecked = item.querySelector('input.owner-radio:checked');\n    const isOtherDept = !!(ownChecked && ownChecked.value === '타 부서 담당');\n    const cpRows = item.querySelectorAll('tr.cp-row');\n\n    if(isOtherDept){\n      // \"타 부서 담당\"으로 정당하게 건너뛴 항목은 진행률상 불이익이 없도록 완료로 간주한다.\n      answered += cpRows.length;\n      domAnswered[domain] += cpRows.length;\n      const deptInput = item.querySelector('.owner-dept-input');\n      const deptMissing = !deptInput || !deptInput.value.trim();\n      if(deptMissing) missingParts.push('담당 부서명 미입력(필수)');\n      // 비어 있는 채로 남아 있으면 눈에 띄게 테두리를 강조해, 이것 때문에 완료가 안 된다는 걸 바로 알 수 있게 한다.\n      if(deptInput) deptInput.classList.toggle('dept-input-required', deptMissing);\n    } else {\n      let itemAnswered = 0;\n      cpRows.forEach(row => {\n        const checked = row.querySelector('input.resp:checked');\n        if(checked){ answered++; domAnswered[domain]++; itemAnswered++; }\n      });\n      if(itemAnswered < cpRows.length){\n        missingParts.push('체크포인트 ' + (cpRows.length - itemAnswered) + '개 미응답');\n      }\n      if(!item.querySelector('input.fam-radio:checked')) missingParts.push('업무 숙지도 미선택');\n      if(!item.querySelector('input.sr-radio:checked')) missingParts.push('자체평가 미선택');\n    }\n\n    if(!ownChecked) missingParts.push('담당여부 미선택');\n\n    if(missingParts.length > 0){\n      incomplete.push({code, title, missingParts});\n    }\n  });\n\n  return {answered, domAnswered, incomplete, totalItems: items.length};\n}\n\nfunction render(){\n  const s = collectStats();\n\n  document.getElementById('ans-count').textContent = s.answered;\n  document.getElementById('progress-fill').style.width = (TOTAL_CP ? (s.answered/TOTAL_CP*100) : 0) + '%';\n\n  Object.keys(DOM_TOTALS).forEach(code => {\n    const fracEl = document.getElementById('dom-' + code + '-frac');\n    const fillEl = document.getElementById('dom-' + code + '-fill');\n    if(fracEl) fracEl.textContent = s.domAnswered[code] + '/' + DOM_TOTALS[code];\n    if(fillEl) fillEl.style.width = (s.domAnswered[code]/DOM_TOTALS[code]*100) + '%';\n    const subEl = document.getElementById('dom-' + code + '-answered');\n    if(subEl) subEl.textContent = s.domAnswered[code];\n  });\n\n  const missingCountBadge = document.getElementById('missing-count-badge');\n  if(missingCountBadge) missingCountBadge.textContent = s.incomplete.length > 0 ? ('(' + s.incomplete.length + '건 남음)') : '';\n  const missingEl = document.getElementById('missing-list');\n  if(s.incomplete.length === 0){\n    missingEl.innerHTML = s.answered > 0\n      ? '<div class=\"missing-all-done\">✓ 모든 항목의 응답을 확인했습니다. 누락된 항목이 없습니다.</div>'\n      : '<div class=\"missing-empty\">아직 응답을 시작하지 않았습니다. 작성을 진행하면 미완료 항목이 여기에 표시됩니다.</div>';\n  } else {\n    missingEl.innerHTML = s.incomplete.map(it =>\n      '<div class=\"missing-item\" data-jump-code=\"' + it.code + '\" style=\"cursor:pointer;\" title=\"클릭하면 해당 항목으로 이동합니다\">'\n      + '<div class=\"mi-head\"><span><span class=\"mi-code\">'+it.code+'</span>'+it.title+'</span></div>'\n      + '<div class=\"mi-what\">' + it.missingParts.join(' · ') + '</div>'\n      + '</div>'\n    ).join('');\n    missingEl.querySelectorAll('.missing-item').forEach(el => {\n      el.addEventListener('click', () => {\n        const target = document.querySelector('.item[data-code=\"' + CSS.escape(el.dataset.jumpCode) + '\"]');\n        if(target){\n          target.classList.remove('js-hidden');\n          target.closest('.domain').classList.remove('js-all-hidden');\n          target.scrollIntoView({behavior:'smooth', block:'start'});\n          target.classList.add('js-highlight');\n          setTimeout(() => target.classList.remove('js-highlight'), 1600);\n        }\n      });\n    });\n  }\n\n  if(typeof applyToolbarFilters === 'function') applyToolbarFilters();\n  if(typeof refreshSideNavMapStatus === 'function') refreshSideNavMapStatus();\n\n  // 방금 막 \"전부 완료\" 상태로 바뀐 순간(이전엔 미완료가 있었는데 지금은 0건)에만 완료 안내를 띄운다.\n  // 이미 완료된 상태에서 화면이 다시 그려질 때마다(응답 하나 더 고칠 때 등) 반복해서 뜨지 않도록,\n  // \"직전 렌더 시점의 미완료 건수\"를 기억해 전환 순간만 잡아낸다.\n  const nowIncomplete = s.incomplete.length;\n  const hasAnyAnswer = s.answered > 0;\n  if(hasAnyAnswer && nowIncomplete === 0 && _prevIncompleteCount > 0){\n    // 막 완료된 \"그 순간\"에 바로 띄우면, 다른 칸에 커서를 옮기려던 사용자가 놀랄 수 있다는 지적에 따라\n    // 살짝 대기(디바운스)한다 — 그 사이 다시 값을 고쳐 미완료로 돌아가면(예: 다른 문항을 손보는 중)\n    // 조용히 취소되고, 정말 손을 뗀 뒤에만(1.1초간 추가 변화 없음) 안내가 뜬다.\n    clearTimeout(_allCompleteModalTimer);\n    _allCompleteModalTimer = setTimeout(() => {\n      if(collectStats().incomplete.length === 0) showAllCompleteModal();\n    }, 1100);\n  } else {\n    clearTimeout(_allCompleteModalTimer);\n  }\n  _prevIncompleteCount = nowIncomplete;\n}\nlet _prevIncompleteCount = Infinity;\nlet _allCompleteModalTimer = null;\n\nfunction showAllCompleteModal(){\n  const modal = document.getElementById('allCompleteModal');\n  if(modal) modal.style.display = 'flex';\n}\nfunction closeAllCompleteModal(){\n  const modal = document.getElementById('allCompleteModal');\n  if(modal) modal.style.display = 'none';\n}\nfunction downloadJSONFromModal(){\n  downloadJSON();\n  closeAllCompleteModal();\n}\n\nfunction confirmIncompleteBeforeDownload(){\n  // 다운로드 직전 완료 여부를 다시 계산해, 미완료 항목이 있으면 그대로 제출할지 확인한다.\n  // collectStats()는 render()가 쓰는 동일한 판정 로직이라 이중 관리 부담이 없다.\n  const s = collectStats();\n  if(s.incomplete.length === 0) return true;\n  return confirm(\n    '⚠ 아직 완료하지 않은 항목이 ' + s.incomplete.length + '건 있습니다.\\n\\n'\n    + '[확인] = 지금 상태 그대로 다운로드합니다 (나중에 이어서 작성해 다시 제출하셔도 됩니다)\\n'\n    + '[취소] = 다운로드하지 않고, 위쪽 \"아직 작성하지 않은 항목\" 목록에서 남은 항목을 마저 작성합니다'\n  );\n}\n\nfunction downloadCSV(){\n  if(!confirmIncompleteBeforeDownload()) return;\n  const dept = document.getElementById('f-dept').value || '';\n  const author = document.getElementById('f-author').value || '';\n  const date = document.getElementById('f-date').value || '';\n  const interviewAvail = (document.getElementById('f-interviewAvail').value || '').replace(/,/g,'，');\n  const interviewContact = (document.getElementById('f-interviewContact').value || '').replace(/,/g,'，');\n  const rows = [['수검부서','작성자','작성일','인터뷰담당자','인터뷰가능시간','도메인','항목코드','항목명','위험도','관련법령','담당여부','담당부서명','담당자성명','업무숙지도','세부체크포인트','응답','응답성격','비고','자체평가','자체평가근거','제출증빙']];\n  document.querySelectorAll('.item').forEach(item => {\n    const domain = item.dataset.domain, code = item.dataset.code, title = item.dataset.title, risk = item.dataset.risk, law = item.dataset.law || '';\n    const note = item.querySelector('.note-input') ? item.querySelector('.note-input').value.replace(/\\n/g,' ').replace(/,/g,'，') : '';\n    const srChecked = item.querySelector('input.sr-radio:checked');\n    const srValue = srChecked ? srChecked.value : '';\n    const srNoteEl = item.querySelector('.sr-note');\n    const srNote = srNoteEl ? srNoteEl.value.replace(/\\n/g,' ').replace(/,/g,'，') : '';\n    const evidenceCheckedArr = Array.from(item.querySelectorAll('.evi-box:checked'))\n      .map(cb => cb.dataset.eviName || cb.closest('label').textContent.trim());\n    const evidenceCustomEl = item.querySelector('.evi-custom-input');\n    if(evidenceCustomEl && evidenceCustomEl.value.trim()) evidenceCheckedArr.push(evidenceCustomEl.value.trim().replace(/\\r?\\n/g, ' / '));\n    const evidenceChecked = evidenceCheckedArr.join(' / ');\n    const ownChecked = item.querySelector('input.owner-radio:checked');\n    const ownValue = ownChecked ? ownChecked.value : '';\n    const ownDeptEl = item.querySelector('.owner-dept-input');\n    const ownDeptText = ownDeptEl ? ownDeptEl.value.replace(/,/g,'，') : '';\n    const ownPersonEl = item.querySelector('.owner-person-input');\n    const ownPersonText = ownPersonEl ? ownPersonEl.value.replace(/,/g,'，') : '';\n    const famChecked = item.querySelector('input.fam-radio:checked');\n    const famValue = famChecked ? famChecked.value : '';\n    item.querySelectorAll('tr.cp-row').forEach(row => {\n      const checked = row.querySelector('input.resp:checked');\n      const val = checked ? checked.value : '';\n      const tier = checked ? (checked.dataset.tier || '') : '';\n      rows.push([dept, author, date, interviewContact, interviewAvail, domain, code, title, risk, law.replace(/,/g,'，'), ownValue, ownDeptText, ownPersonText, famValue, row.dataset.cptext.replace(/,/g,'，'), val, tier, note, srValue, srNote, evidenceChecked]);\n    });\n  });\n  const csv = rows.map(r => r.map(c => '\"'+String(c).replace(/\"/g,'\"\"')+'\"').join(',')).join('\\n');\n  const blob = new Blob(['\\uFEFF'+csv], {type:'text/csv;charset=utf-8;'});\n  const url = URL.createObjectURL(blob);\n  const a = document.createElement('a');\n  const surveyTag = sanitizeForFilename(document.title).slice(0, 40) || '설문';\n  const authorTag = sanitizeForFilename(author) || '작성자미상';\n  const fname = 'IT감사설문_응답_' + sanitizeForFilename(dept || '수검부서') + '_' + authorTag + '_' + surveyTag + '_' + fileTimestampKST() + '__SYSTEM_VERSION_SUFFIX__.csv';\n  a.href = url; a.download = fname;\n  document.body.appendChild(a); a.click(); document.body.removeChild(a);\n  URL.revokeObjectURL(url);\n}\n\nfunction downloadJSON(){\n  if(!confirmIncompleteBeforeDownload()) return;\n  const dept = document.getElementById('f-dept').value || '';\n  const author = document.getElementById('f-author').value || '';\n  const date = document.getElementById('f-date').value || '';\n  const interviewAvail = document.getElementById('f-interviewAvail').value || '';\n  const interviewContact = document.getElementById('f-interviewContact').value || '';\n  const rows = [];\n  document.querySelectorAll('.item').forEach(item => {\n    const domain = item.dataset.domain, code = item.dataset.code, title = item.dataset.title, risk = item.dataset.risk, law = item.dataset.law || '';\n    const note = item.querySelector('.note-input') ? item.querySelector('.note-input').value : '';\n    const srChecked = item.querySelector('input.sr-radio:checked');\n    const srValue = srChecked ? srChecked.value : '';\n    const srNoteEl = item.querySelector('.sr-note');\n    const srNote = srNoteEl ? srNoteEl.value : '';\n    const evidenceCheckedArr2 = Array.from(item.querySelectorAll('.evi-box:checked'))\n      .map(cb => cb.dataset.eviName || cb.closest('label').textContent.trim());\n    const evidenceCustomEl2 = item.querySelector('.evi-custom-input');\n    if(evidenceCustomEl2 && evidenceCustomEl2.value.trim()) evidenceCheckedArr2.push(evidenceCustomEl2.value.trim().replace(/\\r?\\n/g, ' / '));\n    const evidenceChecked = evidenceCheckedArr2.join(' / ');\n    const ownChecked = item.querySelector('input.owner-radio:checked');\n    const ownValue = ownChecked ? ownChecked.value : '';\n    const ownDeptEl = item.querySelector('.owner-dept-input');\n    const ownDeptText = ownDeptEl ? ownDeptEl.value : '';\n    const ownPersonEl = item.querySelector('.owner-person-input');\n    const ownPersonText = ownPersonEl ? ownPersonEl.value : '';\n    const famChecked = item.querySelector('input.fam-radio:checked');\n    const famValue = famChecked ? famChecked.value : '';\n    item.querySelectorAll('tr.cp-row').forEach(row => {\n      const checked = row.querySelector('input.resp:checked');\n      const val = checked ? checked.value : '';\n      const tier = checked ? (checked.dataset.tier || '') : '';\n      rows.push({\n        '수검부서': dept, '작성자': author, '작성일': date,\n        '도메인': domain, '항목코드': code, '항목명': title, '위험도': risk, '관련법령': law,\n        '담당여부': ownValue, '담당부서명': ownDeptText, '담당자성명': ownPersonText, '업무숙지도': famValue,\n        '세부체크포인트': row.dataset.cptext, '응답': val, '응답성격': tier,\n        '비고': note, '자체평가': srValue, '자체평가근거': srNote, '제출증빙': evidenceChecked\n      });\n    });\n  });\n  const payload = {'수검부서': dept, '작성자': author, '작성일': date, '인터뷰담당자': interviewContact, '인터뷰가능시간': interviewAvail, '문항': rows};\n  const blob = new Blob([JSON.stringify(payload, null, 2)], {type:'application/json;charset=utf-8;'});\n  const url = URL.createObjectURL(blob);\n  const a = document.createElement('a');\n  const surveyTag2 = sanitizeForFilename(document.title).slice(0, 40) || '설문';\n  const authorTag2 = sanitizeForFilename(author) || '작성자미상';\n  const fname = 'IT감사설문_응답_' + sanitizeForFilename(dept || '수검부서') + '_' + authorTag2 + '_' + surveyTag2 + '_' + fileTimestampKST() + '__SYSTEM_VERSION_SUFFIX__.json';\n  a.href = url; a.download = fname;\n  document.body.appendChild(a); a.click(); document.body.removeChild(a);\n  URL.revokeObjectURL(url);\n}\n\nfunction sanitizeForFilename(s){\n  return String(s || '').trim()\n    .replace(/[\\\\/:*?\"<>|]/g, '')\n    .replace(/\\s+/g, '_');\n}\n\nfunction fileTimestampKST(){\n  const d = new Date(Date.now() + 9 * 3600000);\n  const pad = (n) => String(n).padStart(2,'0');\n  return d.getUTCFullYear() + pad(d.getUTCMonth()+1) + pad(d.getUTCDate()) + '_' + pad(d.getUTCHours()) + pad(d.getUTCMinutes()) + pad(d.getUTCSeconds());\n}\n\nfunction updateEvidenceFilename(cb){\n  const item = cb.closest('.item');\n  const hint = cb.closest('.evi-item').querySelector('.evi-filename-hint');\n  if(!cb.checked){ hint.style.display = 'none'; return; }\n  const dept = sanitizeForFilename(document.getElementById('f-dept').value) || '수검부서';\n  const code = item.dataset.code;\n  const idx = cb.dataset.eviIdx;\n  const name = sanitizeForFilename(cb.dataset.eviName);\n  const filename = dept + '_' + code + '_' + idx + '_' + name;\n  hint.innerHTML = '저장 파일명: <b>' + filename + '.[원본 확장자]</b> — 스캔·저장 시 이 이름으로 저장해 주세요.';\n  hint.style.display = 'block';\n}\n\nfunction refreshAllEvidenceFilenames(){\n  document.querySelectorAll('.evi-box:checked').forEach(updateEvidenceFilename);\n}\n\nfunction resetAllSilent(){\n  document.querySelectorAll('input.resp').forEach(r => r.checked = false);\n  document.querySelectorAll('.evi-box').forEach(c => { c.checked = false; });\n  document.querySelectorAll('.evi-custom-input').forEach(el => { el.value = ''; });\n  document.querySelectorAll('.evi-filename-hint').forEach(h => { h.style.display = 'none'; });\n  document.querySelectorAll('.note-input').forEach(t => t.value = '');\n  document.querySelectorAll('input.sr-radio').forEach(r => r.checked = false);\n  document.querySelectorAll('.sr-note').forEach(t => t.value = '');\n  document.querySelectorAll('.sr-opt').forEach(el => el.classList.remove('on'));\n  document.querySelectorAll('input.owner-radio').forEach(r => r.checked = false);\n  document.querySelectorAll('.owner-opt').forEach(el => el.classList.remove('on'));\n  document.querySelectorAll('.owner-dept-input').forEach(el => { el.value = ''; el.style.display = 'none'; });\n  document.querySelectorAll('.owner-person-input').forEach(el => { el.value = ''; });\n  document.querySelectorAll('input.fam-radio').forEach(r => r.checked = false);\n  document.querySelectorAll('.fam-opt').forEach(el => el.classList.remove('on'));\n  render();\n}\n\nfunction resetAll(){\n  if(!confirm('모든 응답과 비고 입력을 초기화하시겠습니까? (자동저장된 이어하기 임시본도 함께 삭제됩니다)')) return;\n  clearDraft();\n  resetAllSilent();\n}\n\n/* ===== 작성 가이드 새 창 (도식화) ===== */\nfunction openWritingGuideWindow(){\n  const html = '<!DOCTYPE html><html lang=\"ko\"><head><meta charset=\"UTF-8\"><title>설문 작성 가이드</title><style>'\n    + ':root{--navy:#132845;--navy-2:#1d3a63;--gold:#b8863b;--paper:#f6f3ec;--card:#fff;--ink:#1b2330;--ink-soft:#5a6472;--line:#dcd6c8;--good:#2e7d5b;--good-bg:#e5f2ea;}'\n    + '*{box-sizing:border-box;}body{margin:0;background:#dcd5c4;font-family:\"Pretendard\",\"Noto Sans KR\",sans-serif;color:var(--ink);font-size:15px;}'\n    + '.wgw-shell{max-width:760px;margin:20px auto;background:var(--paper);box-shadow:0 10px 30px rgba(19,40,69,.2);padding-bottom:26px;}'\n    + '.wgw-hero{background:linear-gradient(155deg,var(--navy) 0%,var(--navy-2) 62%,#24406b 100%);color:#f4efe2;padding:24px 32px;}'\n    + '.wgw-hero h1{margin:0 0 6px;font-size:21px;}'\n    + '.wgw-hero .sub{font-size:12.5px;color:#c9d2e2;}'\n    + '.wgw-section{padding:22px 32px 4px;}'\n    + '.wgw-section h2{font-size:16px;color:var(--navy);margin:0 0 12px;border-bottom:2px solid var(--navy);padding-bottom:6px;}'\n    + '.wgw-flow{display:flex;flex-wrap:wrap;gap:8px;align-items:stretch;margin-bottom:10px;}'\n    + '.wgw-step{background:var(--card);border:2px solid var(--navy);border-radius:8px;padding:12px 14px;flex:1 1 140px;min-width:130px;position:relative;}'\n    + '.wgw-step.final{border-color:var(--good);}'\n    + '.wgw-step .num{position:absolute;top:-11px;left:10px;background:var(--navy);color:#f4efe2;width:22px;height:22px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:800;font-family:monospace;}'\n    + '.wgw-step.final .num{background:var(--good);}'\n    + '.wgw-step h4{margin:6px 0 5px;font-size:13px;color:var(--navy);}'\n    + '.wgw-step p{margin:0;font-size:11.5px;color:var(--ink-soft);line-height:1.55;}'\n    + '.wgw-arrow{display:flex;align-items:center;color:var(--gold);font-size:18px;flex:none;}'\n    + '.wgw-mock{background:var(--card);border:1px solid var(--line);border-radius:6px;padding:12px 14px;font-size:11.5px;margin:10px 0 16px;}'\n    + '.wgw-mock-row{display:flex;align-items:center;gap:8px;margin-bottom:6px;flex-wrap:wrap;}'\n    + '.wgw-tag{font-family:monospace;font-size:9px;background:var(--navy);color:#f4efe2;padding:2px 6px;border-radius:3px;flex:none;white-space:nowrap;}'\n    + '.wgw-note{font-size:12px;color:var(--ink-soft);background:#eef0f6;border:1px solid #c9d0e0;border-radius:6px;padding:10px 14px;margin:14px 32px 20px;line-height:1.7;}'\n    + '@media (max-width:600px){.wgw-flow{flex-direction:column;}.wgw-arrow{transform:rotate(90deg);align-self:center;}}'\n    + '</style></head><body>'\n    + '<div class=\"wgw-shell\">'\n      + '<div class=\"wgw-hero\"><h1>🖼 설문 작성 가이드</h1><div class=\"sub\">이 창은 설문 탭과 별개로 열려 있으니, 옆에 띄워두고 참고하면서 작성하시면 됩니다.</div></div>'\n      + '<div class=\"wgw-section\"><h2>① 항목 하나, 이렇게 작성하세요</h2>'\n        + '<div class=\"wgw-flow\">'\n          + '<div class=\"wgw-step\"><div class=\"num\">1</div><h4>담당여부</h4><p>내 업무인지 표시. 타 부서 일이면 \"타 부서 담당\"도 정답입니다.</p></div>'\n          + '<div class=\"wgw-arrow\">→</div>'\n          + '<div class=\"wgw-step\"><div class=\"num\">2</div><h4>숙지도</h4><p>이 업무를 얼마나 알고 있는지 표시.</p></div>'\n          + '<div class=\"wgw-arrow\">→</div>'\n          + '<div class=\"wgw-step\"><div class=\"num\">3</div><h4>체크포인트</h4><p>표의 각 줄마다 실제 이행 현황을 선택.</p></div>'\n          + '<div class=\"wgw-arrow\">→</div>'\n          + '<div class=\"wgw-step\"><div class=\"num\">4</div><h4>자체평가</h4><p>실제로 얼마나 잘 하고 있다고 생각하는지 본인 의견.</p></div>'\n        + '</div>'\n        + '<div class=\"wgw-mock\">'\n          + '<div class=\"wgw-mock-row\"><span class=\"wgw-tag\">항목 제목</span> 이 부분은 항목의 이름입니다 (수정 불가)</div>'\n          + '<div class=\"wgw-mock-row\"><span class=\"wgw-tag\">①②</span> 담당여부·숙지도는 화면 위쪽 버튼으로 선택</div>'\n          + '<div class=\"wgw-mock-row\"><span class=\"wgw-tag\">③</span> 표 형태 — 한 줄이 질문 하나, 오른쪽 열 중 하나를 클릭</div>'\n          + '<div class=\"wgw-mock-row\"><span class=\"wgw-tag\">📎</span> 증빙자료 체크박스 — 체크하면 권장 파일명이 뜸(그 이름으로 저장)</div>'\n          + '<div class=\"wgw-mock-row\"><span class=\"wgw-tag\">📎 자유입력</span> 목록에 없는 자료명, 또는 <b>증빙이 없거나 다른 것으로 대체</b>되는 경우 그 사정을 적는 칸(체크박스 목록 바로 아래)</div>'\n          + '<div class=\"wgw-mock-row\"><span class=\"wgw-tag\">④</span> 자체평가 + 비고(응답이 \"아니오\"·\"부분\"일 때 사유) — 맨 아래 텍스트 칸</div>'\n          + '<div class=\"wgw-mock-row\"><span class=\"wgw-tag\">🗓</span> 화면 맨 위 \"인터뷰 가능 시간대\" — 선택 입력, 인터뷰 일정 조율용</div>'\n        + '</div>'\n      + '</div>'\n      + '<div class=\"wgw-section\"><h2>② 다 쓰셨으면, 이렇게 제출하세요</h2>'\n        + '<div class=\"wgw-flow\">'\n          + '<div class=\"wgw-step\"><div class=\"num\">1</div><h4>진행률 확인</h4><p>상단 \"작성 진행 현황\" 패널에서 미완료 항목이 없는지 확인.</p></div>'\n          + '<div class=\"wgw-arrow\">→</div>'\n          + '<div class=\"wgw-step\"><div class=\"num\">2</div><h4>파일 다운로드</h4><p>[결과 CSV] 또는 [결과 JSON] 버튼 클릭 → 파일이 저장됨.</p></div>'\n          + '<div class=\"wgw-arrow\">→</div>'\n          + '<div class=\"wgw-step final\"><div class=\"num\">3</div><h4>감사역에게 전달</h4><p>메일·메신저 등으로 그 파일을 감사역에게 보내면 끝.</p></div>'\n        + '</div>'\n        + '<div class=\"wgw-mock\">'\n          + '<div class=\"wgw-mock-row\"><span class=\"wgw-tag\">📋</span> \"그룹웨어 협조문용 요약표\" 버튼을 누르면 부서 회신용 협조문에 바로 붙여넣을 수 있는 요약표도 만들 수 있습니다.</div>'\n        + '</div>'\n      + '</div>'\n      + '<div class=\"wgw-note\">💡 이 창은 설문 화면과 별개이니, 스크롤해서 항목을 작성하는 동안 창을 계속 열어두고 참고하셔도 됩니다. 궁금한 점이 해소되면 이 창은 닫으셔도 됩니다.</div>'\n    + '</div>'\n    + '</body></html>';\n  const blob = new Blob([html], {type:'text/html;charset=utf-8;'});\n  const url = URL.createObjectURL(blob);\n  window.open(url, '_blank', 'width=820,height=900');\n}\n\n/* ===== 그룹웨어 협조문용 요약표 (이 설문 문서 자신의 응답 기준) ===== */\nfunction toggleGroupwarePanel(){\n  const panel = document.getElementById('groupwarePanel');\n  const open = panel.style.display !== 'none';\n  panel.style.display = open ? 'none' : 'block';\n  if(!open) buildGroupwareSummary();\n}\n\nfunction escGw(s){ return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }\n\nfunction buildGroupwareSummary(){\n  const dept = document.getElementById('f-dept').value || '(미입력)';\n  const author = document.getElementById('f-author').value || '(미입력)';\n  const date = document.getElementById('f-date').value || '(미입력)';\n  const dueDateEl = document.getElementById('f-dueDateDisplay');\n  const dueDate = dueDateEl ? dueDateEl.textContent.trim() : '(미지정)';\n  const surveyKind = document.title || '(제목 없음)';\n\n  let yes = 0, partial = 0, no = 0, na = 0;\n  const issues = [];\n  const evidenceByItem = [];\n  document.querySelectorAll('.item').forEach(item => {\n    const code = item.dataset.code, title = item.dataset.title, risk = item.dataset.risk;\n    const noteEl = item.querySelector('.note-input');\n    const note = noteEl ? noteEl.value.trim() : '';\n    let itemHasIssue = false;\n    item.querySelectorAll('tr.cp-row').forEach(row => {\n      const checked = row.querySelector('input.resp:checked');\n      if(!checked) return;\n      const tier = checked.dataset.tier || '';\n      if(tier === 'good') yes++;\n      else if(tier === 'neutral'){ partial++; itemHasIssue = true; }\n      else if(tier === 'na') na++;\n      else { no++; itemHasIssue = true; }\n    });\n    if(itemHasIssue) issues.push({code, title, risk, note});\n\n    const checkedEvi = Array.from(item.querySelectorAll('.evi-box:checked'))\n      .map(cb => cb.dataset.eviName || cb.closest('label').textContent.trim());\n    const customEviEl = item.querySelector('.evi-custom-input');\n    if(customEviEl && customEviEl.value.trim()) checkedEvi.push(customEviEl.value.trim().replace(/\\r?\\n/g, ' / '));\n    if(checkedEvi.length > 0) evidenceByItem.push({code, title, items: checkedEvi});\n  });\n  const total = yes + partial + no + na;\n\n  const issueRows = issues.length === 0\n    ? '<tr><td colspan=\"4\" style=\"padding:8px 10px;border:1px solid #ccc;text-align:center;color:#777;\">부분이행·미흡 응답 없음</td></tr>'\n    : issues.sort((a,b) => (a.risk==='상'?0:a.risk==='중'?1:2) - (b.risk==='상'?0:b.risk==='중'?1:2)).map(it =>\n        '<tr><td style=\"padding:6px 10px;border:1px solid #ccc;\">' + escGw(it.code) + '</td>'\n        + '<td style=\"padding:6px 10px;border:1px solid #ccc;\">' + escGw(it.title) + '</td>'\n        + '<td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">' + escGw(it.risk) + '</td>'\n        + '<td style=\"padding:6px 10px;border:1px solid #ccc;\">' + escGw(it.note || '-') + '</td></tr>'\n      ).join('');\n\n  const evidenceRows = evidenceByItem.length === 0\n    ? '<tr><td colspan=\"3\" style=\"padding:8px 10px;border:1px solid #ccc;text-align:center;color:#777;\">제출 예정으로 체크된 증빙자료 없음</td></tr>'\n    : evidenceByItem.map(e =>\n        '<tr><td style=\"padding:6px 10px;border:1px solid #ccc;\">' + escGw(e.code) + '</td>'\n        + '<td style=\"padding:6px 10px;border:1px solid #ccc;\">' + escGw(e.title) + '</td>'\n        + '<td style=\"padding:6px 10px;border:1px solid #ccc;\">' + escGw(e.items.join(', ')) + '</td></tr>'\n      ).join('');\n\n  const infoRow = (label, val) =>\n    '<tr><td style=\"padding:6px 10px;border:1px solid #ccc;background:#f1ede1;font-weight:700;width:130px;\">' + escGw(label) + '</td>'\n    + '<td style=\"padding:6px 10px;border:1px solid #ccc;\">' + escGw(val) + '</td></tr>';\n\n  const html = '<div style=\"font-family:Pretendard,sans-serif;font-size:13px;color:#1b2330;\">'\n    + '<h4 style=\"margin:0 0 6px;\">0. 설문 작성 정보 (협조문·시행문 서두에 그대로 활용)</h4>'\n    + '<table style=\"border-collapse:collapse;width:100%;font-size:12.5px;margin-bottom:16px;\">'\n      + infoRow('설문지 종류', surveyKind)\n      + infoRow('수검부서', dept)\n      + infoRow('작성자', author)\n      + infoRow('작성일', date)\n      + infoRow('회신 기한', dueDate)\n      + infoRow('전체 응답 건수', total + '건')\n    + '</table>'\n    + '<h4 style=\"margin:14px 0 6px;\">1. 응답 현황 요약</h4>'\n    + '<table style=\"border-collapse:collapse;width:100%;font-size:12.5px;\">'\n      + '<tr style=\"background:#f1ede1;\"><th style=\"padding:6px 10px;border:1px solid #ccc;\">이행</th><th style=\"padding:6px 10px;border:1px solid #ccc;\">부분이행</th><th style=\"padding:6px 10px;border:1px solid #ccc;\">미흡</th><th style=\"padding:6px 10px;border:1px solid #ccc;\">해당없음</th></tr>'\n      + '<tr><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">' + yes + '</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">' + partial + '</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">' + no + '</td><td style=\"padding:6px 10px;border:1px solid #ccc;text-align:center;\">' + na + '</td></tr>'\n    + '</table>'\n    + '<h4 style=\"margin:16px 0 6px;\">2. 부분이행·미흡 항목 목록 (위험도 순)</h4>'\n    + '<table style=\"border-collapse:collapse;width:100%;font-size:12.5px;\">'\n      + '<tr style=\"background:#f1ede1;\"><th style=\"padding:6px 10px;border:1px solid #ccc;\">항목코드</th><th style=\"padding:6px 10px;border:1px solid #ccc;\">항목명</th><th style=\"padding:6px 10px;border:1px solid #ccc;\">위험도</th><th style=\"padding:6px 10px;border:1px solid #ccc;\">비고</th></tr>'\n      + issueRows\n    + '</table>'\n    + '<h4 style=\"margin:16px 0 6px;\">3. 제출 예정 증빙자료 목록</h4>'\n    + '<table style=\"border-collapse:collapse;width:100%;font-size:12.5px;\">'\n      + '<tr style=\"background:#f1ede1;\"><th style=\"padding:6px 10px;border:1px solid #ccc;\">항목코드</th><th style=\"padding:6px 10px;border:1px solid #ccc;\">항목명</th><th style=\"padding:6px 10px;border:1px solid #ccc;\">증빙자료명</th></tr>'\n      + evidenceRows\n    + '</table>'\n  + '</div>';\n\n  document.getElementById('groupwareSummaryPreview').innerHTML = html;\n  document.getElementById('gwCopyBtn').disabled = false;\n  document.getElementById('gwDownloadBtn').disabled = false;\n}\n\nasync function copyGroupwareSummary(){\n  const el = document.getElementById('groupwareSummaryPreview');\n  if(!el.innerHTML.trim()){ alert('먼저 [요약표 새로고침]을 눌러 표를 만들어 주세요.'); return; }\n  try{\n    if(navigator.clipboard && window.ClipboardItem){\n      const blobHtml = new Blob([el.innerHTML], {type:'text/html'});\n      const blobText = new Blob([el.innerText], {type:'text/plain'});\n      await navigator.clipboard.write([new ClipboardItem({'text/html': blobHtml, 'text/plain': blobText})]);\n      alert('표를 클립보드에 복사했습니다. 그룹웨어 협조문 본문에 [붙여넣기(Ctrl+V)] 해 주세요.');\n    } else {\n      const range = document.createRange();\n      range.selectNode(el);\n      window.getSelection().removeAllRanges();\n      window.getSelection().addRange(range);\n      document.execCommand('copy');\n      window.getSelection().removeAllRanges();\n      alert('표를 클립보드에 복사했습니다. 그룹웨어 협조문 본문에 [붙여넣기(Ctrl+V)] 해 주세요.');\n    }\n  }catch(e){\n    alert('클립보드 복사에 실패했습니다 (' + e.message + '). 아래 표를 마우스로 드래그해 직접 복사해 주세요.');\n  }\n}\n\nfunction downloadGroupwareSummary(){\n  const inner = document.getElementById('groupwareSummaryPreview').innerHTML;\n  if(!inner.trim()){ alert('먼저 [요약표 새로고침]을 눌러 표를 만들어 주세요.'); return; }\n  const dept = document.getElementById('f-dept').value || '수검부서';\n  const fullHtml = '<!DOCTYPE html><html lang=\"ko\"><head><meta charset=\"UTF-8\"><title>설문 응답 요약표</title></head><body>' + inner + '</body></html>';\n  const blob = new Blob([fullHtml], {type:'text/html;charset=utf-8;'});\n  const url = URL.createObjectURL(blob);\n  const a = document.createElement('a');\n  a.href = url; a.download = 'IT감사설문_요약표_' + sanitizeForFilename(dept) + '__SYSTEM_VERSION_SUFFIX__.html';\n  document.body.appendChild(a); a.click(); document.body.removeChild(a);\n  URL.revokeObjectURL(url);\n}\n\n/* ===== 이어하기: 작성 중 내용을 브라우저에 자동저장 (창을 닫아도 다음에 이어서 작성) ===== */\nconst DRAFT_STORAGE_KEY = 'itaudit_survey_draft_v1::' + (document.title || 'default');\nconst DRAFT_TEXT_FIELDS = ['note-input','sr-note','owner-dept-input','owner-person-input','evi-custom-input'];\nlet _draftSaveTimer = null;\n\nfunction collectDraftFields(){\n  const fields = {};\n  document.querySelectorAll('input.resp:checked, input.sr-radio:checked, input.owner-radio:checked, input.fam-radio:checked').forEach(el => {\n    fields[el.name] = el.value;\n  });\n  document.querySelectorAll('.evi-box:checked').forEach(cb => {\n    const item = cb.closest('.item');\n    if(!item) return;\n    fields['evi::' + item.dataset.code + '::' + cb.dataset.eviIdx] = '1';\n  });\n  document.querySelectorAll(DRAFT_TEXT_FIELDS.map(c => '.' + c).join(',')).forEach(el => {\n    const item = el.closest('.item');\n    if(!item || !el.value) return;\n    const cls = DRAFT_TEXT_FIELDS.find(c => el.classList.contains(c));\n    fields['text::' + item.dataset.code + '::' + cls] = el.value;\n  });\n  ['f-dept','f-author','f-date','f-interviewAvail','f-interviewContact'].forEach(id => {\n    const el = document.getElementById(id);\n    if(el && el.value) fields[id] = el.value;\n  });\n  return fields;\n}\n\nfunction kstISOStringLocal(){\n  // 브라우저 시간대와 무관하게 항상 대한민국 표준시(KST, UTC+9) 기준으로 기록합니다.\n  const d = new Date(Date.now() + 9 * 3600000);\n  const pad = (n) => String(n).padStart(2,'0');\n  return d.getUTCFullYear() + '-' + pad(d.getUTCMonth()+1) + '-' + pad(d.getUTCDate()) + 'T' + pad(d.getUTCHours()) + ':' + pad(d.getUTCMinutes()) + ':' + pad(d.getUTCSeconds()) + '+09:00';\n}\n\nfunction saveDraftNow(){\n  try{\n    localStorage.setItem(DRAFT_STORAGE_KEY, JSON.stringify({savedAt: kstISOStringLocal(), fields: collectDraftFields()}));\n  }catch(e){ /* 저장공간 부족 등은 조용히 무시 — 다운로드 기능은 여전히 정상 작동 */ }\n}\n\nfunction saveDraftDebounced(){\n  clearTimeout(_draftSaveTimer);\n  _draftSaveTimer = setTimeout(saveDraftNow, 500);\n}\n\nfunction restoreDraft(){\n  let saved;\n  try{ saved = JSON.parse(localStorage.getItem(DRAFT_STORAGE_KEY)); }catch(e){ return null; }\n  if(!saved || !saved.fields) return null;\n  const f = saved.fields;\n  document.querySelectorAll('input.resp, input.sr-radio, input.owner-radio, input.fam-radio').forEach(el => {\n    if(f[el.name] !== undefined && el.value === f[el.name]){\n      el.checked = true;\n      el.dispatchEvent(new Event('change', {bubbles:true}));\n    }\n  });\n  document.querySelectorAll('.evi-box').forEach(cb => {\n    const item = cb.closest('.item');\n    if(!item) return;\n    const key = 'evi::' + item.dataset.code + '::' + cb.dataset.eviIdx;\n    if(f[key]){\n      cb.checked = true;\n      cb.dispatchEvent(new Event('change', {bubbles:true}));\n    }\n  });\n  document.querySelectorAll(DRAFT_TEXT_FIELDS.map(c => '.' + c).join(',')).forEach(el => {\n    const item = el.closest('.item');\n    if(!item) return;\n    const cls = DRAFT_TEXT_FIELDS.find(c => el.classList.contains(c));\n    const key = 'text::' + item.dataset.code + '::' + cls;\n    if(f[key] !== undefined) el.value = f[key];\n  });\n  ['f-dept','f-author','f-date','f-interviewAvail','f-interviewContact'].forEach(id => {\n    const el = document.getElementById(id);\n    if(el && f[id] !== undefined) el.value = f[id];\n  });\n  return saved.savedAt || true;\n}\n\nfunction clearDraft(){\n  try{ localStorage.removeItem(DRAFT_STORAGE_KEY); }catch(e){ /* non-fatal */ }\n}\n\n/* ===== 이전에 다운로드한 JSON 파일을 불러와 이어작성 (실수나 브라우저 초기화로 자동저장이 유실되었을 때의 대안) ===== */\nfunction restoreFromJSONFile(file){\n  const reader = new FileReader();\n  reader.onload = (e) => {\n    let payload;\n    try{ payload = JSON.parse(e.target.result); }catch(err){ alert('JSON 파일을 읽을 수 없습니다: ' + err.message); return; }\n    const rows = payload['문항'];\n    if(!Array.isArray(rows) || rows.length === 0){ alert('이 파일에서 설문 응답 데이터를 찾을 수 없습니다. (이 설문지에서 내려받은 JSON 파일이 맞는지 확인해 주세요)'); return; }\n    if(!confirm('이 JSON 파일의 응답으로 현재 화면 내용을 덮어씁니다. 계속할까요?')) return;\n\n    if(payload['수검부서']) document.getElementById('f-dept').value = payload['수검부서'];\n    if(payload['작성자']) document.getElementById('f-author').value = payload['작성자'];\n    if(payload['작성일']) document.getElementById('f-date').value = payload['작성일'];\n    if(payload['인터뷰가능시간']) document.getElementById('f-interviewAvail').value = payload['인터뷰가능시간'];\n    if(payload['인터뷰담당자']) document.getElementById('f-interviewContact').value = payload['인터뷰담당자'];\n\n    const byCode = {};\n    rows.forEach(r => { const c = r['항목코드']; if(!c) return; (byCode[c] = byCode[c] || []).push(r); });\n\n    Object.keys(byCode).forEach(code => {\n      const item = document.querySelector('.item[data-code=\"' + CSS.escape(code) + '\"]');\n      if(!item) return;\n      const itemRows = byCode[code];\n      const first = itemRows[0];\n\n      if(first['담당여부']){\n        const r = item.querySelector('input.owner-radio[value=\"' + CSS.escape(first['담당여부']) + '\"]');\n        if(r){ r.checked = true; r.dispatchEvent(new Event('change', {bubbles:true})); }\n      }\n      if(first['담당부서명']){\n        const el = item.querySelector('.owner-dept-input');\n        if(el) el.value = first['담당부서명'];\n      }\n      if(first['담당자성명']){\n        const el = item.querySelector('.owner-person-input');\n        if(el) el.value = first['담당자성명'];\n      }\n      if(first['업무숙지도']){\n        const r = item.querySelector('input.fam-radio[value=\"' + CSS.escape(first['업무숙지도']) + '\"]');\n        if(r){ r.checked = true; r.dispatchEvent(new Event('change', {bubbles:true})); }\n      }\n      if(first['비고']){\n        const el = item.querySelector('.note-input');\n        if(el) el.value = first['비고'];\n      }\n      if(first['자체평가']){\n        const r = item.querySelector('input.sr-radio[value=\"' + CSS.escape(first['자체평가']) + '\"]');\n        if(r){ r.checked = true; r.dispatchEvent(new Event('change', {bubbles:true})); }\n      }\n      if(first['자체평가근거']){\n        const el = item.querySelector('.sr-note');\n        if(el) el.value = first['자체평가근거'];\n      }\n      if(first['제출증빙']){\n        const names = String(first['제출증빙']).split(' / ').map(s => s.trim()).filter(Boolean);\n        const matchedNames = [];\n        item.querySelectorAll('.evi-box').forEach(cb => {\n          if(names.includes(cb.dataset.eviName)){ cb.checked = true; matchedNames.push(cb.dataset.eviName); cb.dispatchEvent(new Event('change', {bubbles:true})); }\n        });\n        const leftover = names.filter(n => !matchedNames.includes(n));\n        if(leftover.length){\n          const customEl = item.querySelector('.evi-custom-input');\n          if(customEl) customEl.value = leftover.join(', ');\n        }\n      }\n\n      itemRows.forEach(r => {\n        const cpText = r['세부체크포인트'];\n        const respVal = r['응답'];\n        if(!cpText || !respVal) return;\n        item.querySelectorAll('tr.cp-row').forEach(row => {\n          if(row.dataset.cptext === cpText){\n            const radio = row.querySelector('input.resp[value=\"' + CSS.escape(respVal) + '\"]');\n            if(radio){ radio.checked = true; radio.dispatchEvent(new Event('change', {bubbles:true})); }\n          }\n        });\n      });\n    });\n\n    render();\n    growAllTextareas();\n    saveDraftNow();\n    alert('JSON 파일의 응답을 불러왔습니다. 이어서 작성해 주세요.');\n  };\n  reader.readAsText(file, 'UTF-8');\n}\n\nconst resumeJsonFileInputEl = document.getElementById('resumeJsonFileInput');\nif(resumeJsonFileInputEl) resumeJsonFileInputEl.addEventListener('change', (e) => {\n  const file = e.target.files[0];\n  if(file) restoreFromJSONFile(file);\n  e.target.value = '';\n});\n\ndocument.addEventListener('change', function(e){\n  if(e.target.classList.contains('resp')) render();\n  if(e.target.classList.contains('sr-radio')){\n    const group = e.target.closest('.sr-options');\n    if(group) group.querySelectorAll('.sr-opt').forEach(el => el.classList.remove('on'));\n    e.target.closest('.sr-opt').classList.add('on');\n    render();\n\n  }\n  if(e.target.classList.contains('owner-radio')){\n    const group = e.target.closest('.owner-options');\n    if(group) group.querySelectorAll('.owner-opt').forEach(el => el.classList.remove('on'));\n    e.target.closest('.owner-opt').classList.add('on');\n    const deptInput = group ? group.querySelector('.owner-dept-input') : null;\n    const isOtherDept = e.target.value === '타 부서 담당';\n    if(deptInput){\n      deptInput.style.display = isOtherDept ? 'inline-block' : 'none';\n      // \"타 부서 담당\" 선택 즉시 커서를 부서명 입력칸으로 옮겨, 필수 입력임을 자연스럽게 알아채게 한다.\n      if(isOtherDept) setTimeout(() => deptInput.focus(), 0);\n    }\n    const warnNote = e.target.closest('.owner-check').querySelector('.owner-warn-note');\n    if(warnNote) warnNote.classList.toggle('active', isOtherDept);\n    updateOwnerSkipState(e.target.closest('.item'));\n    render();\n  }\n  if(e.target.classList.contains('fam-radio')){\n    const group = e.target.closest('.fam-options');\n    if(group) group.querySelectorAll('.fam-opt').forEach(el => el.classList.remove('on'));\n    const tier = e.target.value === '잘 알고 있음' ? 'high' : (e.target.value === '잘 모름' ? 'low' : 'mid');\n    e.target.closest('.fam-opt').classList.add('on', tier);\n    render();\n  }\n  if(e.target.classList.contains('evi-box')){ updateEvidenceFilename(e.target); syncItemFootHeight(e.target.closest('.item')); }\n  if(e.target.id === 'f-dept') refreshAllEvidenceFilenames();\n});\n\ndocument.addEventListener('change', function(e){\n  if(e.target.classList.contains('resp') || e.target.classList.contains('sr-radio') || e.target.classList.contains('owner-radio')\n    || e.target.classList.contains('fam-radio') || e.target.classList.contains('evi-box') || e.target.id === 'f-dept'\n    || e.target.id === 'f-author' || e.target.id === 'f-date') saveDraftDebounced();\n});\n\ndocument.addEventListener('input', function(e){\n  if(e.target.classList.contains('owner-dept-input')) render();\n  if(e.target.classList.contains('note-input') || e.target.classList.contains('sr-note') || e.target.classList.contains('owner-dept-input')\n    || e.target.classList.contains('owner-person-input') || e.target.classList.contains('evi-custom-input')\n    || e.target.id === 'f-dept' || e.target.id === 'f-author' || e.target.id === 'f-date' || e.target.id === 'f-interviewAvail' || e.target.id === 'f-interviewContact') saveDraftDebounced();\n});\n\n/* ===== Toolbar: domain nav / jump / search / filter / back-to-top ===== */\nlet currentFilter = 'all';\n\nfunction updateOwnerSkipState(item){\n  if(!item) return;\n  const checked = item.querySelector('input.owner-radio:checked');\n  const isOther = !!(checked && checked.value === '타 부서 담당');\n  item.classList.toggle('other-dept-skip', isOther);\n  item.querySelectorAll('input.fam-radio').forEach(r => { r.disabled = isOther; });\n  item.querySelectorAll('input.resp').forEach(r => { r.disabled = isOther; });\n  item.querySelectorAll('.evi-box').forEach(r => { r.disabled = isOther; });\n  item.querySelectorAll('.note-input').forEach(r => { r.disabled = isOther; });\n  item.querySelectorAll('input.sr-radio').forEach(r => { r.disabled = isOther; });\n}\n\nfunction itemIsIncomplete(item){\n  const ownChecked = item.querySelector('input.owner-radio:checked');\n  if(!ownChecked) return true;\n  if(ownChecked.value === '타 부서 담당'){\n    const deptInput = item.querySelector('.owner-dept-input');\n    return !deptInput || !deptInput.value.trim();\n  }\n  const cpRows = item.querySelectorAll('tr.cp-row');\n  let answeredCp = 0;\n  cpRows.forEach(row => { if(row.querySelector('input.resp:checked')) answeredCp++; });\n  if(answeredCp < cpRows.length) return true;\n  if(!item.querySelector('input.fam-radio:checked')) return true;\n  if(!item.querySelector('input.sr-radio:checked')) return true;\n  return false;\n}\n\nfunction itemStatus(item){\n  // 3가지 상태로 분류: notstarted(미작성) / inprogress(작성중) / complete(완료).\n  // 필터 칩이랑 사이드바 배지가 이 함수 하나로만 판단하도록 통일합니다.\n  const ownChecked = item.querySelector('input.owner-radio:checked');\n  const famChecked = item.querySelector('input.fam-radio:checked');\n  const srChecked = item.querySelector('input.sr-radio:checked');\n  const cpRows = item.querySelectorAll('tr.cp-row');\n  let answeredCp = 0;\n  cpRows.forEach(row => { if(row.querySelector('input.resp:checked')) answeredCp++; });\n  const deptInput = item.querySelector('.owner-dept-input');\n  const anyProgress = !!ownChecked || !!famChecked || !!srChecked || answeredCp > 0 || (deptInput && deptInput.value.trim());\n  if(!anyProgress) return 'notstarted';\n  return itemIsIncomplete(item) ? 'inprogress' : 'complete';\n}\n\nfunction initSurveyZoom(){\n  const STORAGE_KEY = 'itaudit_survey_zoom_v1';\n  const STEPS = [80, 90, 100, 110, 125, 140, 160];\n  function getLevel(){\n    try{ return Number(localStorage.getItem(STORAGE_KEY)) || 100; }catch(e){ return 100; }\n  }\n  function apply(pct){\n    document.body.style.zoom = pct + '%';\n    const label = document.getElementById('zoomPctLabel');\n    if(label) label.textContent = pct + '%';\n    try{ localStorage.setItem(STORAGE_KEY, String(pct)); }catch(e){ /* non-fatal */ }\n  }\n  function step(direction){\n    const current = getLevel();\n    const idx = STEPS.reduce((closest, v, i) => Math.abs(v-current) < Math.abs(STEPS[closest]-current) ? i : closest, 0);\n    const nextIdx = Math.min(STEPS.length-1, Math.max(0, idx + direction));\n    apply(STEPS[nextIdx]);\n  }\n  const inBtn = document.getElementById('zoomInBtn');\n  const outBtn = document.getElementById('zoomOutBtn');\n  const resetBtn = document.getElementById('zoomResetBtn');\n  if(inBtn) inBtn.addEventListener('click', () => step(1));\n  if(outBtn) outBtn.addEventListener('click', () => step(-1));\n  if(resetBtn) resetBtn.addEventListener('click', () => apply(100));\n  apply(getLevel());\n}\n\nfunction autoGrowTextarea(el){\n  if(!el) return;\n  el.style.height = 'auto';\n  el.style.height = (el.scrollHeight + 2) + 'px';\n}\nfunction growAllTextareas(){\n  // 초기 렌더/이어서 작성(자동저장·JSON 불러오기) 직후, 이미 값이 들어있는 자유입력 칸도\n  // 첫 화면부터 알맞은 높이로 펼쳐지도록 일괄 적용한다. (oninput은 사용자가 타이핑할 때만 발동)\n  document.querySelectorAll('.note-input, .sr-note, .evi-custom-input').forEach(autoGrowTextarea);\n  document.querySelectorAll('.item').forEach(syncItemFootHeight);\n}\nfunction syncItemFootHeight(item){\n  // \"왼쪽 증빙 칸이 늘어나는 만큼 오른쪽 비고 칸도 맞춰 늘어나야 깔끔하다\"는 요청에 대응.\n  // 항목 하단(증빙 자유입력 vs 비고)의 두 입력창 중 더 긴 쪽 높이에 짧은 쪽을 맞춘다.\n  if(!item) return;\n  const noteEl = item.querySelector('.note-input');\n  const eviEl = item.querySelector('.evi-custom-input');\n  if(!noteEl || !eviEl) return;\n  noteEl.style.height = 'auto';\n  eviEl.style.height = 'auto';\n  const target = Math.max(noteEl.scrollHeight, eviEl.scrollHeight, 64) + 2;\n  noteEl.style.height = target + 'px';\n  eviEl.style.height = target + 'px';\n}\n\nfunction openQuickMenu(){\n  const nav = document.getElementById('sideNavMap');\n  const backdrop = document.getElementById('quickMenuBackdrop');\n  if(nav) nav.classList.add('force-show');\n  if(backdrop) backdrop.classList.add('show');\n}\nfunction closeQuickMenu(){\n  const nav = document.getElementById('sideNavMap');\n  const backdrop = document.getElementById('quickMenuBackdrop');\n  if(nav) nav.classList.remove('force-show');\n  if(backdrop) backdrop.classList.remove('show');\n}\nfunction initQuickMenuFab(){\n  // 1660px 미만(일반 사무용 노트북 다수 포함) 화면에서는 \"빠른 메뉴\"가 상시 노출되지 않는 대신,\n  // 화면 아래쪽 플로팅 버튼을 눌러 필요할 때만 여닫는 오버레이 형태로 대체 제공한다.\n  const fab = document.getElementById('quickMenuFab');\n  const backdrop = document.getElementById('quickMenuBackdrop');\n  if(fab) fab.addEventListener('click', openQuickMenu);\n  if(backdrop) backdrop.addEventListener('click', closeQuickMenu);\n}\n\nfunction initToolbar(){\n  const domainRow = document.getElementById('domainJumpRow');\n  const jumpSelect = document.getElementById('jumpSelect');\n  const seenDom = {};\n  document.querySelectorAll('.domain').forEach(domEl => {\n    const code = domEl.dataset.domain;\n    if(seenDom[code]) return;\n    seenDom[code] = true;\n    const h2 = domEl.querySelector('.domain-head h2');\n    const title = h2 ? h2.textContent.trim() : code;\n    const chip = document.createElement('button');\n    chip.className = 'domain-jump-chip';\n    chip.textContent = 'D-' + code + ' ' + title;\n    chip.addEventListener('click', () => {\n      domEl.scrollIntoView({behavior:'smooth', block:'start'});\n    });\n    domainRow.appendChild(chip);\n  });\n\n  document.querySelectorAll('.item').forEach(item => {\n    const opt = document.createElement('option');\n    opt.value = item.dataset.code;\n    opt.textContent = item.dataset.code + ' — ' + item.dataset.title;\n    jumpSelect.appendChild(opt);\n  });\n\n  buildSideNavMap();\n\n  jumpSelect.addEventListener('change', () => {\n    if(!jumpSelect.value) return;\n    const target = document.querySelector('.item[data-code=\"' + CSS.escape(jumpSelect.value) + '\"]');\n    if(target){\n      target.classList.remove('js-hidden');\n      target.closest('.domain').classList.remove('js-all-hidden');\n      target.scrollIntoView({behavior:'smooth', block:'start'});\n      target.classList.add('js-highlight');\n      setTimeout(() => target.classList.remove('js-highlight'), 1600);\n    }\n    jumpSelect.value = '';\n  });\n\n  document.getElementById('searchBox').addEventListener('input', applyToolbarFilters);\n  document.querySelectorAll('.filter-chip').forEach(btn => {\n    btn.addEventListener('click', () => {\n      document.querySelectorAll('.filter-chip').forEach(b => b.classList.remove('active'));\n      btn.classList.add('active');\n      currentFilter = btn.dataset.filter;\n      applyToolbarFilters();\n    });\n  });\n\n  const backBtn = document.getElementById('backToTopBtn');\n  window.addEventListener('scroll', () => {\n    backBtn.classList.toggle('show', window.scrollY > 500);\n  });\n  backBtn.addEventListener('click', () => window.scrollTo({top:0, behavior:'smooth'}));\n}\n\nfunction buildSideNavMap(){\n  const nav = document.getElementById('sideNavMap');\n  if(!nav) return;\n  let html = '<button type=\"button\" class=\"snm-close-btn\" onclick=\"closeQuickMenu()\">✕ 닫기</button><h5>빠른 메뉴</h5>'\n    + '<div class=\"snm-actions\">'\n      + '<button class=\"snm-action-btn\" onclick=\"window.print()\">🖨 인쇄 / PDF</button>'\n      + '<button class=\"snm-action-btn\" onclick=\"downloadCSV()\">⬇ 결과 CSV</button>'\n      + '<button class=\"snm-action-btn\" onclick=\"downloadJSON()\">⬇ 결과 JSON</button>'\n      + '<button class=\"snm-action-btn\" onclick=\"document.getElementById(\\'resumeJsonFileInput\\').click()\">📥 JSON 불러와 이어작성</button>'\n      + '<button class=\"snm-action-btn\" onclick=\"openSummaryInfographic()\">📊 요약·전체 리뷰 보기</button>'\n      + '<button class=\"snm-action-btn\" onclick=\"toggleGroupwarePanel(); document.getElementById(\\'groupwarePanel\\').scrollIntoView({behavior:\\'smooth\\'});\">📋 그룹웨어 요약표</button>'\n    + '</div>'\n    + '<h5>항목 바로가기</h5>';\n  const seenDom = {};\n  document.querySelectorAll('.domain').forEach(domEl => {\n    const code = domEl.dataset.domain;\n    if(seenDom[code]) return;\n    seenDom[code] = true;\n    const h2 = domEl.querySelector('.domain-head h2');\n    const title = h2 ? h2.textContent.trim() : code;\n    html += '<div class=\"snm-domain\">'\n      + '<div class=\"snm-domain-title\" data-jump-domain=\"' + code + '\">D-' + code + ' ' + title + '</div>';\n    domEl.querySelectorAll('.item').forEach(item => {\n      html += '<div class=\"snm-item-link\" data-jump-code=\"' + item.dataset.code + '\">'\n        + '<div class=\"snm-item-top\"><span class=\"snm-item-code\">' + item.dataset.code + '</span><span class=\"snm-item-status\" data-status-badge></span></div>'\n        + '<span class=\"snm-item-title-text\">' + item.dataset.title + '</span>'\n        + '</div>';\n    });\n    html += '</div>';\n  });\n  nav.innerHTML = html;\n\n  nav.querySelectorAll('[data-jump-domain]').forEach(el => {\n    el.addEventListener('click', () => {\n      const domEl = document.querySelector('.domain[data-domain=\"' + CSS.escape(el.dataset.jumpDomain) + '\"]');\n      if(domEl) domEl.scrollIntoView({behavior:'smooth', block:'start'});\n      closeQuickMenu();\n    });\n  });\n  nav.querySelectorAll('[data-jump-code]').forEach(el => {\n    el.addEventListener('click', () => {\n      const target = document.querySelector('.item[data-code=\"' + CSS.escape(el.dataset.jumpCode) + '\"]');\n      if(target){\n        target.classList.remove('js-hidden');\n        target.closest('.domain').classList.remove('js-all-hidden');\n        target.scrollIntoView({behavior:'smooth', block:'start'});\n        target.classList.add('js-highlight');\n        setTimeout(() => target.classList.remove('js-highlight'), 1600);\n      }\n      closeQuickMenu();\n    });\n  });\n  refreshSideNavMapStatus();\n}\n\nfunction refreshSideNavMapStatus(){\n  const nav = document.getElementById('sideNavMap');\n  if(!nav) return;\n  const STATUS_LABEL = {complete:'작성완료', inprogress:'작성중', notstarted:'미작성'};\n  document.querySelectorAll('.item').forEach(item => {\n    const link = nav.querySelector('[data-jump-code=\"' + CSS.escape(item.dataset.code) + '\"]');\n    if(!link) return;\n    const st = itemStatus(item);\n    link.classList.toggle('answered', st === 'complete');\n    const badge = link.querySelector('[data-status-badge]');\n    if(badge){\n      badge.textContent = STATUS_LABEL[st];\n      badge.className = 'snm-item-status st-' + st;\n    }\n  });\n}\n\nfunction applyToolbarFilters(){\n  const term = document.getElementById('searchBox').value.trim().toLowerCase();\n  let visibleCount = 0, totalCount = 0;\n\n  document.querySelectorAll('.domain').forEach(domEl => {\n    let domainHasVisible = false;\n    domEl.querySelectorAll('.item').forEach(item => {\n      totalCount++;\n      let visible = true;\n\n      if(term){\n        const haystack = (item.dataset.title + ' ' + item.querySelector('.item-desc').textContent + ' '\n          + Array.from(item.querySelectorAll('.q')).map(q => q.textContent).join(' ')).toLowerCase();\n        if(!haystack.includes(term)) visible = false;\n      }\n      if(visible && currentFilter === 'notstarted' && itemStatus(item) !== 'notstarted') visible = false;\n      if(visible && currentFilter === 'inprogress' && itemStatus(item) !== 'inprogress') visible = false;\n      if(visible && currentFilter === 'complete' && itemStatus(item) !== 'complete') visible = false;\n      if(visible && currentFilter === 'risk-상' && item.dataset.risk !== '상') visible = false;\n      if(visible && currentFilter === 'risk-중' && item.dataset.risk !== '중') visible = false;\n      if(visible && currentFilter === 'risk-하' && item.dataset.risk !== '하') visible = false;\n\n      item.classList.toggle('js-hidden', !visible);\n      if(visible){ visibleCount++; domainHasVisible = true; }\n    });\n    domEl.classList.toggle('js-all-hidden', !domainHasVisible);\n  });\n\n  const countEl = document.getElementById('searchResultCount');\n  if(term || currentFilter !== 'all'){\n    countEl.textContent = visibleCount + ' / ' + totalCount + '개 항목 표시 중';\n  } else {\n    countEl.textContent = '';\n  }\n}\n\ninitDashboard();\ninitToolbar();\ninitSurveyZoom();\ninitQuickMenuFab();\nconst _draftSavedAt = restoreDraft();\nrender();\ngrowAllTextareas();\nif(_draftSavedAt){\n  const banner = document.getElementById('draftRestoreBanner');\n  if(banner){\n    banner.style.display = 'flex';\n    const timeEl = document.getElementById('draftRestoreTime');\n    if(timeEl && typeof _draftSavedAt === 'string'){\n      try{\n        const dd = new Date(new Date(_draftSavedAt).getTime() + 9 * 3600000);\n        const pad2 = (n) => String(n).padStart(2,'0');\n        timeEl.textContent = dd.getUTCFullYear() + '-' + pad2(dd.getUTCMonth()+1) + '-' + pad2(dd.getUTCDate()) + ' ' + pad2(dd.getUTCHours()) + ':' + pad2(dd.getUTCMinutes()) + ' (KST)';\n      }catch(e){ timeEl.textContent = ''; }\n    }\n    const discardBtn = document.getElementById('discardDraftBtn');\n    if(discardBtn) discardBtn.addEventListener('click', () => {\n      if(!confirm('자동저장된 임시본을 지우고 새로 시작할까요? 현재 화면의 응답도 함께 초기화됩니다.')) return;\n      clearDraft();\n      resetAllSilent();\n      banner.style.display = 'none';\n    });\n  }\n}\n\n/* ===== 📊 요약 인포그래픽 — 이 부서가 작성한 내용을 한 페이지로 요약해서 보여준다.\n   제출용 JSON/CSV와 별개로, 부서 내부 보고·공유용으로 바로 보고 인쇄(A4)할 수 있는 화면이다. ===== */\nfunction domainTitleOf(code){\n  const h2 = document.querySelector('.domain[data-domain=\"' + CSS.escape(code) + '\"] .domain-head h2');\n  return h2 ? h2.textContent.trim() : code;\n}\n\nfunction collectInfographicStats(){\n  const items = document.querySelectorAll('.item');\n  const tierCounts = {good:0, neutral:0, bad:0, na:0};\n  const byDomain = {};\n  const byRisk = {'상':{total:0,bad:0}, '중':{total:0,bad:0}, '하':{total:0,bad:0}};\n  const badItems = [];\n  const domainOrder = [];\n  const allItems = []; // 전체 항목 리뷰용 — 미흡 여부와 무관하게 모든 항목의 응답 내용을 그대로 담는다\n  let ownerOtherCount = 0;\n  let srMismatchCount = 0;\n  let totalCp = 0;\n\n  items.forEach(item => {\n    const code = item.dataset.code, title = item.dataset.title, domain = item.dataset.domain, risk = item.dataset.risk || '중';\n    if(!byDomain[domain]){ byDomain[domain] = {total:0, good:0, neutral:0, bad:0, na:0, title: domainTitleOf(domain)}; domainOrder.push(domain); }\n    const ownChecked = item.querySelector('input.owner-radio:checked');\n    const ownVal = ownChecked ? ownChecked.value : '';\n    if(ownVal === '타 부서 담당' || ownVal === '공동 담당') ownerOtherCount++;\n    const ownDeptEl = item.querySelector('.owner-dept-input');\n    const ownPersonEl = item.querySelector('.owner-person-input');\n    const famChecked = item.querySelector('input.fam-radio:checked');\n    const noteEl = item.querySelector('.note-input');\n    const srChecked = item.querySelector('input.sr-radio:checked');\n    const srNoteEl = item.querySelector('.sr-note');\n    const eviChecked = Array.from(item.querySelectorAll('.evi-box:checked')).map(cb => cb.dataset.eviName || cb.closest('label').textContent.trim());\n    const eviCustomEl = item.querySelector('.evi-custom-input');\n    if(eviCustomEl && eviCustomEl.value.trim()) eviChecked.push(eviCustomEl.value.trim().replace(/\\r?\\n/g, ' / '));\n\n    let itemHasBad = false;\n    const checkpoints = [];\n    item.querySelectorAll('tr.cp-row').forEach(row => {\n      const checked = row.querySelector('input.resp:checked');\n      const cptext = row.dataset.cptext || '';\n      if(!checked){ checkpoints.push({cptext, tier:'', resp:''}); return; } // 미응답도 리뷰 목록에는 표시(빈 상태로), 단 통계 집계에서는 제외\n      const tier = checked.dataset.tier || '';\n      checkpoints.push({cptext, tier, resp: checked.value});\n      if(!Object.prototype.hasOwnProperty.call(tierCounts, tier)) return;\n      tierCounts[tier]++;\n      byDomain[domain][tier]++;\n      byDomain[domain].total++;\n      totalCp++;\n      if(byRisk[risk]){ byRisk[risk].total++; if(tier === 'bad') byRisk[risk].bad++; }\n      if(tier === 'bad'){\n        itemHasBad = true;\n        badItems.push({code, title, risk, cptext});\n      }\n    });\n\n    if(srChecked && srChecked.value === '잘함' && itemHasBad) srMismatchCount++;\n\n    allItems.push({\n      code, title, domain, domainTitle: domainTitleOf(domain), risk,\n      own: ownVal, ownDept: ownDeptEl ? ownDeptEl.value : '', ownPerson: ownPersonEl ? ownPersonEl.value : '',\n      fam: famChecked ? famChecked.value : '', note: noteEl ? noteEl.value : '',\n      sr: srChecked ? srChecked.value : '', srNote: srNoteEl ? srNoteEl.value : '',\n      evidence: eviChecked, checkpoints, hasBad: itemHasBad\n    });\n  });\n\n  return {tierCounts, byDomain, byRisk, badItems, ownerOtherCount, srMismatchCount, totalCp, allItems, domainOrder};\n}\n\nfunction buildItemReviewHtml(stats, esc3){\n  const RV_BADGE = {good:'✅ 이행', neutral:'🟡 부분이행', bad:'🚩 미흡', na:'⬜ 해당없음', blank:'— 미응답'};\n  const byDomain = {};\n  stats.allItems.forEach(it => { (byDomain[it.domain] = byDomain[it.domain] || []).push(it); });\n  return stats.domainOrder.map(dcode => {\n    const list = byDomain[dcode] || [];\n    if(list.length === 0) return '';\n    const domTitle = list[0].domainTitle;\n    const itemsHtml = list.map(it => {\n      const isOtherDept = it.own === '타 부서 담당';\n      const cpHtml = isOtherDept\n        ? ('<div class=\"rv-skip\">↪ 타 부서 담당으로 표시됨' + (it.ownDept ? (' — 담당부서: ' + esc3(it.ownDept)) : '') + '</div>')\n        : '<ul class=\"rv-cp-list\">' + it.checkpoints.map(cp => {\n            const t = cp.tier || 'blank';\n            return '<li><span class=\"rv-cp-badge ' + t + '\">' + (RV_BADGE[t] || RV_BADGE.blank) + '</span><span>' + esc3(cp.cptext) + '</span></li>';\n          }).join('') + '</ul>';\n      const metaBits = [];\n      if(it.own && !isOtherDept) metaBits.push('담당여부: <b>' + esc3(it.own) + '</b>');\n      if(it.fam) metaBits.push('숙지도: <b>' + esc3(it.fam) + '</b>');\n      if(it.sr) metaBits.push('자체평가: <b>' + esc3(it.sr) + '</b>');\n      if(it.ownPerson) metaBits.push('관련 담당자: <b>' + esc3(it.ownPerson) + '</b>');\n      return '<div class=\"rv-item' + (it.hasBad ? ' rv-bad' : '') + '\">'\n        + '<div class=\"rv-item-head\"><span class=\"rv-item-code\">' + esc3(it.code) + '</span><span class=\"rv-item-title\">' + esc3(it.title) + '</span><span class=\"rv-badge\">위험도 ' + esc3(it.risk) + '</span></div>'\n        + (metaBits.length ? ('<div class=\"rv-meta-row\">' + metaBits.join(' · ') + '</div>') : '')\n        + cpHtml\n        + (it.note ? ('<div class=\"rv-note-block\">📝 비고: ' + esc3(it.note) + '</div>') : '')\n        + (it.srNote ? ('<div class=\"rv-note-block\">🗒 자체평가 근거: ' + esc3(it.srNote) + '</div>') : '')\n        + (it.evidence.length ? ('<div class=\"rv-note-block\">📎 제출 예정 증빙: ' + esc3(it.evidence.join(', ')) + '</div>') : '')\n      + '</div>';\n    }).join('');\n    return '<div class=\"rv-domain-head\">D-' + esc3(dcode) + ' ' + esc3(domTitle) + '</div>' + itemsHtml;\n  }).join('');\n}\n\nfunction buildSummaryInfographicHtml(stats){\n  const dept = (document.getElementById('f-dept') || {}).value || '(부서 미입력)';\n  const author = (document.getElementById('f-author') || {}).value || '(작성자 미입력)';\n  const date = (document.getElementById('f-date') || {}).value || '';\n  const auditName = document.title || '';\n  const esc3 = (s) => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;');\n  const T = stats.tierCounts;\n  const total = stats.totalCp || 0;\n  const implRate = total > 0 ? Math.round((T.good + T.neutral) / total * 100) : 0;\n  const hiBadCount = stats.byRisk['상'] ? stats.byRisk['상'].bad : 0;\n  const nowStr = new Date(Date.now() + 9*3600000).toISOString().slice(0,16).replace('T',' ') + ' (KST)';\n\n  // 도넛 차트: conic-gradient로 4단계 응답 분포를 그린다(외부 라이브러리 없이 순수 CSS).\n  const order = [['good','#2e7d5b'], ['neutral','#b8863b'], ['bad','#a23b2e'], ['na','#9aa3b0']];\n  let acc = 0;\n  const stops = order.map(([k,color]) => {\n    const pct = total > 0 ? (T[k]/total*100) : 0;\n    const start = acc; acc += pct;\n    return color + ' ' + start.toFixed(2) + '% ' + acc.toFixed(2) + '%';\n  }).join(', ');\n  const donutStyle = total > 0 ? ('background: conic-gradient(' + stops + ');') : 'background:#e5e1d4;';\n\n  const TIER_LABEL_KR = {good:'양호(이행)', neutral:'보통(부분이행)', bad:'개선필요(미흡)', na:'해당없음'};\n  const legendHtml = order.map(([k,color]) =>\n    '<div class=\"legend-row\"><span class=\"legend-dot\" style=\"background:' + color + ';\"></span>'\n    + '<span class=\"legend-label\">' + TIER_LABEL_KR[k] + '</span>'\n    + '<span class=\"legend-val\">' + T[k] + '건 (' + (total > 0 ? Math.round(T[k]/total*100) : 0) + '%)</span></div>'\n  ).join('');\n\n  const domainRows = Object.keys(stats.byDomain)\n    .map(k => stats.byDomain[k])\n    .filter(d => d.total > 0)\n    .sort((a,b) => (b.bad/b.total) - (a.bad/a.total))\n    .map(d => {\n      const segs = order.map(([k,color]) => {\n        const pct = d.total > 0 ? (d[k]/d.total*100) : 0;\n        return pct > 0 ? ('<span style=\"display:inline-block;height:100%;width:' + pct.toFixed(2) + '%;background:' + color + ';\"></span>') : '';\n      }).join('');\n      return '<div class=\"dom-row\">'\n        + '<div class=\"dom-label\">' + esc3(d.title) + '</div>'\n        + '<div class=\"dom-bar-track\">' + segs + '</div>'\n        + '<div class=\"dom-count\">' + d.total + '건 · 미흡 ' + d.bad + '건</div>'\n      + '</div>';\n    }).join('');\n\n  const badTableRows = stats.badItems.length === 0\n    ? '<tr><td colspan=\"3\" style=\"padding:14px;color:#5a6472;text-align:center;\">개선 필요(미흡) 응답이 없습니다.</td></tr>'\n    : stats.badItems.map(b =>\n        '<tr><td class=\"mono\" style=\"white-space:nowrap;\">' + esc3(b.code) + ' <span class=\"risk-chip risk-' + esc3(b.risk) + '\">' + esc3(b.risk) + '</span></td>'\n        + '<td>' + esc3(b.title) + '</td><td>' + esc3(b.cptext) + '</td></tr>'\n      ).join('');\n\n  // 📎 제출 예정 증빙자료 목록 — 제출 전 부서가 자신이 체크한 증빙 전체를 한 곳에서 훑어볼 수 있도록,\n  // 미흡 여부와 무관하게 증빙이 하나라도 체크/입력된 모든 항목을 모은다.\n  const evidenceItems = stats.allItems.filter(it => it.evidence && it.evidence.length > 0);\n  const evidenceListRows = evidenceItems.length === 0\n    ? '<tr><td colspan=\"3\" style=\"padding:14px;color:#5a6472;text-align:center;\">제출 예정으로 체크된 증빙자료가 없습니다.</td></tr>'\n    : evidenceItems.map(it =>\n        '<tr><td class=\"mono\" style=\"white-space:nowrap;\">' + esc3(it.code) + '</td>'\n        + '<td>' + esc3(it.title) + '</td><td>' + esc3(it.evidence.join(', ')) + '</td></tr>'\n      ).join('');\n\n  return '<!DOCTYPE html><html lang=\"ko\"><head><meta charset=\"UTF-8\"><title>설문 응답 요약 — ' + esc3(dept) + '</title><style>'\n    + '@page{size:A4;margin:14mm;}'\n    + '*{box-sizing:border-box;}'\n    + 'body{font-family:\\'Pretendard\\',\\'Noto Sans KR\\',sans-serif;margin:0;background:#efece2;color:#1b2330;}'\n    + '.wrap{max-width:800px;margin:24px auto;background:#fff;box-shadow:0 8px 30px rgba(19,40,69,.18);}'\n    + '.hero{background:#132845;color:#f4efe2;padding:28px 34px;}'\n    + '.hero .eyebrow{font-family:\\'IBM Plex Mono\\',monospace;font-size:11px;letter-spacing:.1em;color:#e4c78a;text-transform:uppercase;}'\n    + '.hero h1{margin:6px 0 10px;font-size:24px;}'\n    + '.hero .meta{font-size:12.5px;color:#c9d2e2;line-height:1.8;}'\n    + '.body{padding:26px 34px 34px;}'\n    + '.stat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:26px;}'\n    + '.stat-card{border:1px solid #dcd6c8;border-radius:8px;padding:14px 12px;text-align:center;}'\n    + '.stat-card .num{font-family:\\'IBM Plex Mono\\',monospace;font-size:26px;font-weight:700;color:#132845;}'\n    + '.stat-card .lbl{font-size:11px;color:#5a6472;margin-top:4px;line-height:1.5;}'\n    + '.stat-card.warn .num{color:#a23b2e;}'\n    + 'h2.sec{font-size:14px;color:#132845;border-left:4px solid #b8863b;padding-left:10px;margin:26px 0 14px;}'\n    + '.donut-row{display:flex;align-items:center;gap:30px;margin-bottom:8px;}'\n    + '.donut{width:150px;height:150px;border-radius:50%;flex:none;position:relative;' + donutStyle + '}'\n    + '.donut::after{content:\"\";position:absolute;inset:24px;background:#fff;border-radius:50%;}'\n    + '.donut-center{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;}'\n    + '.donut-center b{font-family:\\'IBM Plex Mono\\',monospace;font-size:22px;color:#132845;}'\n    + '.donut-center span{font-size:10px;color:#5a6472;}'\n    + '.legend{flex:1;}'\n    + '.legend-row{display:flex;align-items:center;gap:8px;padding:5px 0;font-size:12.5px;border-bottom:1px dashed #e5e1d4;}'\n    + '.legend-dot{width:11px;height:11px;border-radius:50%;flex:none;}'\n    + '.legend-label{flex:1;}'\n    + '.legend-val{font-family:\\'IBM Plex Mono\\',monospace;color:#5a6472;}'\n    + '.dom-row{display:grid;grid-template-columns:150px 1fr 110px;align-items:center;gap:10px;padding:6px 0;font-size:12px;}'\n    + '.dom-label{color:#1b2330;}'\n    + '.dom-bar-track{height:14px;background:#efece2;border-radius:3px;overflow:hidden;white-space:nowrap;}'\n    + '.dom-count{font-family:\\'IBM Plex Mono\\',monospace;font-size:11px;color:#5a6472;text-align:right;}'\n    + 'table{width:100%;border-collapse:collapse;font-size:12px;}'\n    + 'th,td{padding:7px 9px;border-bottom:1px solid #ece7d9;text-align:left;}'\n    + 'th{background:#f1ede1;font-size:10px;color:#5a6472;text-transform:uppercase;}'\n    + '.risk-chip{font-family:\\'IBM Plex Mono\\',monospace;font-size:9.5px;padding:1px 5px;border-radius:8px;font-weight:700;}'\n    + '.risk-상{background:#f7e6e2;color:#a23b2e;} .risk-중{background:#f7edd9;color:#b8863b;} .risk-하{background:#e5f2ea;color:#2e7d5b;}'\n    + '.note-box{background:#faf8f0;border:1px solid #dcd6c8;border-radius:6px;padding:12px 14px;font-size:12px;color:#5a6472;line-height:1.7;margin-top:10px;}'\n    + '.footer{padding:16px 34px;font-size:10.5px;color:#8a92a0;border-top:1px solid #ece7d9;}'\n    + '.rv-domain-head{font-size:13px;font-weight:700;color:#132845;background:#f1ede1;padding:8px 12px;margin:22px 0 10px;border-radius:4px;}'\n    + '.rv-item{border:1px solid #dcd6c8;border-radius:6px;padding:10px 14px;margin-bottom:10px;break-inside:avoid;page-break-inside:avoid;}'\n    + '.rv-item.rv-bad{border-left:4px solid #a23b2e;}'\n    + '.rv-item-head{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:6px;}'\n    + '.rv-item-code{font-family:\\'IBM Plex Mono\\',monospace;font-size:10.5px;color:#5a6472;}'\n    + '.rv-item-title{font-weight:700;font-size:13px;color:#1b2330;flex:1;}'\n    + '.rv-badge{font-size:10px;font-family:\\'IBM Plex Mono\\',monospace;padding:2px 7px;border-radius:9px;background:#eef0f6;color:#463b8a;white-space:nowrap;}'\n    + '.rv-skip{font-size:11.5px;color:#a23b2e;background:#fdecea;border-radius:4px;padding:6px 9px;}'\n    + '.rv-cp-list{margin:4px 0 0;padding:0;list-style:none;}'\n    + '.rv-cp-list li{display:flex;gap:8px;align-items:flex-start;font-size:11.8px;padding:3px 0;border-top:1px dashed #ece7d9;}'\n    + '.rv-cp-list li:first-child{border-top:none;}'\n    + '.rv-cp-badge{flex:none;font-family:\\'IBM Plex Mono\\',monospace;font-size:10px;font-weight:700;padding:1px 7px;border-radius:8px;white-space:nowrap;}'\n    + '.rv-cp-badge.good{background:#e5f2ea;color:#2e7d5b;} .rv-cp-badge.neutral{background:#f7edd9;color:#b8863b;} .rv-cp-badge.bad{background:#f7e6e2;color:#a23b2e;} .rv-cp-badge.na{background:#eee;color:#5a6472;} .rv-cp-badge.blank{background:#f2f2f2;color:#aaa;}'\n    + '.rv-meta-row{display:flex;flex-wrap:wrap;gap:6px 16px;font-size:11.3px;color:#5a6472;margin-top:6px;}'\n    + '.rv-meta-row b{color:#1b2330;}'\n    + '.rv-note-block{font-size:11.5px;color:#1b2330;background:#faf8f0;border-radius:4px;padding:6px 9px;margin-top:6px;line-height:1.6;}'\n    + '.print-btn{position:fixed;top:16px;right:16px;background:#132845;color:#f4efe2;border:none;border-radius:6px;padding:9px 16px;font-size:12.5px;cursor:pointer;}'\n    + '@media print{.print-btn{display:none;}body{background:#fff;}.wrap{box-shadow:none;margin:0;max-width:none;}}'\n    + '</style></head><body>'\n    + '<button class=\"print-btn no-print\" onclick=\"window.print()\">인쇄 / PDF 저장</button>'\n    + '<div class=\"wrap\">'\n      + '<div class=\"hero\"><div class=\"eyebrow\">IT AUDIT · SURVEY RESPONSE SUMMARY</div><h1>📊 설문 응답 요약</h1>'\n        + '<div class=\"meta\">' + esc3(auditName) + '<br>수검부서: <b>' + esc3(dept) + '</b> · 작성자: <b>' + esc3(author) + '</b> · 작성일: ' + esc3(date) + '</div></div>'\n      + '<div class=\"body\">'\n        + '<div class=\"stat-grid\">'\n          + '<div class=\"stat-card\"><div class=\"num\">' + total + '</div><div class=\"lbl\">전체 응답 체크포인트</div></div>'\n          + '<div class=\"stat-card\"><div class=\"num\">' + implRate + '%</div><div class=\"lbl\">이행률<br>(양호+보통 비중)</div></div>'\n          + '<div class=\"stat-card' + (hiBadCount > 0 ? ' warn' : '') + '\"><div class=\"num\">' + hiBadCount + '</div><div class=\"lbl\">위험도 \"상\" 중<br>미흡 응답</div></div>'\n          + '<div class=\"stat-card\"><div class=\"num\">' + stats.ownerOtherCount + '</div><div class=\"lbl\">타 부서 담당 ·<br>공동 담당 표시</div></div>'\n        + '</div>'\n        + '<h2 class=\"sec\">전체 응답 분포</h2>'\n        + '<div class=\"donut-row\"><div class=\"donut\"><div class=\"donut-center\"><b>' + implRate + '%</b><span>이행률</span></div></div>'\n          + '<div class=\"legend\">' + legendHtml + '</div></div>'\n        + (Object.keys(stats.byDomain).length > 1 ? ('<h2 class=\"sec\">영역별 이행 현황 (미흡 비율 높은 순)</h2><div class=\"dom-list\">' + domainRows + '</div>') : '')\n        + '<h2 class=\"sec\">🚩 개선 필요(미흡) 응답 — ' + stats.badItems.length + '건</h2>'\n        + '<table><tr><th>항목코드/위험도</th><th>항목명</th><th>체크포인트</th></tr>' + badTableRows + '</table>'\n        + (stats.srMismatchCount > 0 ? ('<div class=\"note-box\">💡 자체평가에서 \"잘함\"으로 표시했지만 실제로는 미흡 응답이 포함된 항목이 <b>' + stats.srMismatchCount + '건</b> 있습니다. 제출 전 다시 한 번 확인해 보시는 것을 권장합니다.</div>') : '')\n        + '<h2 class=\"sec\">📎 제출 예정 증빙자료 목록 — ' + evidenceItems.length + '건</h2>'\n        + '<table><tr><th>항목코드</th><th>항목명</th><th>제출 예정 증빙자료</th></tr>' + evidenceListRows + '</table>'\n        + '<h2 class=\"sec\" style=\"page-break-before:always;\">📋 전체 항목 리뷰 (' + stats.allItems.length + '개 항목 — 제출 전 마지막 확인용)</h2>'\n        + '<p style=\"font-size:11.5px;color:#5a6472;margin:0 0 14px;line-height:1.6;\">아래는 이 설문에서 응답한 모든 항목의 담당여부·체크포인트 응답·비고·자체평가·증빙을 그대로 모은 목록입니다. 위 요약 통계와 달리 미흡 여부와 관계없이 전체 항목을 다 담고 있으니, 제출 전 빠뜨리거나 잘못 적은 내용이 없는지 처음부터 훑어보시기 바랍니다.</p>'\n        + buildItemReviewHtml(stats, esc3)\n      + '</div>'\n      + '<div class=\"footer\">생성일시: ' + nowStr + ' · 이 페이지는 부서 내부 확인·공유용이며, 감사팀 제출용 파일은 별도로 \"결과 JSON/CSV 다운로드\"를 이용해 주세요. · A4 인쇄에 최적화되어 있습니다.</div>'\n    + '</div>'\n  + '</body></html>';\n}\n\nfunction openSummaryInfographic(){\n  const stats = collectInfographicStats();\n  if(stats.totalCp === 0){\n    alert('아직 응답한 체크포인트가 없습니다. 먼저 설문 항목에 응답해 주세요.');\n    return;\n  }\n  const html = buildSummaryInfographicHtml(stats);\n  const blob = new Blob([html], {type:'text/html;charset=utf-8;'});\n  const url = URL.createObjectURL(blob);\n  window.open(url, '_blank', 'width=880,height=1000');\n}\n<\/script>\n\n</body>\n</html>\n";
